import { computed, ref, type ComputedRef, type Ref } from 'vue';
import {
    getObservabilityHealth,
    getObservabilityMetricsOverview,
    getObservabilityAuditLogs,
    deleteExpiredTokens
} from '@api';
import type { ObservabilityHealth, ObservabilityMetricsSummary, AuditEventItem } from '@types';
import type { AdminAuditFilters } from '@/modules/admin/types.ts';
import { useAsyncAction } from '@/infrastructure/composables/useAsyncAction.ts';

export interface UseAdminObservabilityReturn {
    health: Ref<ObservabilityHealth | undefined>;
    metrics: Ref<ObservabilityMetricsSummary | undefined>;
    auditEvents: ComputedRef<AuditEventItem[]>;
    auditTotal: ComputedRef<number>;
    loadingHealth: Ref<boolean>;
    loadingMetrics: Ref<boolean>;
    loadingAudit: Ref<boolean>;
    errorHealth: Ref<string | undefined>;
    errorMetrics: Ref<string | undefined>;
    errorAudit: Ref<string | undefined>;
    fetchHealth: () => Promise<void>;
    fetchMetrics: () => Promise<void>;
    fetchAuditLogs: (filters?: AdminAuditFilters) => Promise<void>;
    fetchAll: () => Promise<void>;
    clearingExpiredTokens: Ref<boolean>;
    clearExpiredTokens: () => Promise<void>;
}

/**
 * Unified composable for the Admin observability dashboard.
 *
 * It exposes the three contract-backed endpoints behind one shared state:
 * - GET /observability/health
 * - GET /observability/metrics/overview
 * - GET /observability/audit
 *
 * Each is a {@link useAsyncAction}: the loading/data/error bookkeeping is written once there
 * rather than three times here, and every fetcher resolves rather than rejects, so a partially
 * available stack still renders the panels that answered.
 *
 * @returns Shared state (payloads, per-call loading flags and error messages) plus the four
 *  fetchers.
 */
export const useAdminObservability = (): UseAdminObservabilityReturn => {
    const {
        data: health,
        error: errorHealth,
        loading: loadingHealth,
        run: runHealth
    } = useAsyncAction(() => getObservabilityHealth().then((response) => response.data), {
        fallbackErrorMessage: 'Failed to load health data'
    });

    const {
        data: metrics,
        error: errorMetrics,
        loading: loadingMetrics,
        run: runMetrics
    } = useAsyncAction(() => getObservabilityMetricsOverview().then((response) => response.data), {
        fallbackErrorMessage: 'Failed to load metrics data'
    });

    /**
     * The audit call answers with items AND a total, so its payload is the envelope; the two are
     * split back out below rather than tracked as separate state that could disagree.
     */
    const {
        data: audit,
        error: errorAudit,
        loading: loadingAudit,
        run: runAuditLogs
    } = useAsyncAction(
        (filters: AdminAuditFilters = {}) =>
            getObservabilityAuditLogs({
                actor: filters.actor,
                action: filters.action,
                outcome: filters.outcome,
                since: filters.since,
                limit: filters.limit
            }).then((response) => response.data),
        { fallbackErrorMessage: 'Failed to load audit logs' }
    );

    const auditEvents = computed(() => audit.value?.items ?? []);
    const auditTotal = computed(() => audit.value?.total ?? 0);

    /**
     * The three fetchers resolve with nothing: every consumer reads the state refs, and a
     * `Promise<void>` is what `AdminAuditTab`'s `onSearch` prop is typed to take.
     *
     * @returns A promise resolving once `health` or `errorHealth` is set.
     */
    const fetchHealth = () => runHealth().then(() => {});

    /**
     * @returns A promise resolving once `metrics` or `errorMetrics` is set.
     */
    const fetchMetrics = () => runMetrics().then(() => {});

    /**
     * Loads the audit log page matching the given filters.
     *
     * @param filters - Actor/action/outcome/since/limit criteria; defaults to no filtering at all.
     * @returns A promise resolving once `auditEvents` + `auditTotal`, or `errorAudit`, are set.
     */
    const fetchAuditLogs = (filters: AdminAuditFilters = {}) =>
        runAuditLogs(filters).then(() => {});

    /**
     * Loads health, metrics and audit logs in parallel, for the initial dashboard render.
     *
     * @returns A promise resolving once all three calls have settled.
     */
    const fetchAll = () =>
        Promise.all([fetchHealth(), fetchMetrics(), fetchAuditLogs()]).then(() => {});

    const clearingExpiredTokens = ref(false);

    /**
     * Purges the expired refresh tokens.
     *
     * The odd one out here, and deliberately not a {@link useAsyncAction}: the other four are
     * READS whose failure is a panel that renders an error, so swallowing the rejection into an
     * `error` ref is exactly right. This is a WRITE whose outcome the visitor asked for and is
     * owed either way, so it REJECTS and lets the view answer with the toast it already writes.
     * Folding it into `useAsyncAction` would mean the view polling an error ref after the fact to
     * decide which message to show.
     *
     * What it does own is the pending flag, because that is bookkeeping rather than copy — the
     * view binds it to the button and never sets it.
     *
     * @returns A promise resolving on success and rejecting on failure. The pending flag is
     *  cleared either way.
     */
    const clearExpiredTokens = (): Promise<void> => {
        clearingExpiredTokens.value = true;
        return deleteExpiredTokens()
            .then(() => undefined)
            .finally(() => {
                clearingExpiredTokens.value = false;
            });
    };

    return {
        health,
        metrics,
        auditEvents,
        auditTotal,
        loadingHealth,
        loadingMetrics,
        loadingAudit,
        errorHealth,
        errorMetrics,
        errorAudit,
        fetchHealth,
        fetchMetrics,
        fetchAuditLogs,
        fetchAll,
        clearingExpiredTokens,
        clearExpiredTokens
    };
};

tests/unit/infrastructure/utils/logger.s.source:
/**
 * The console boundary — `src/infrastructure/logger.ts`.
 *
 * Worth its own cases because everything else in the app now routes through it: a level or scope
 * comparison that is wrong one way silences an error, and wrong the other way ships per-navigation
 * noise to a production console. Neither is visible from a call site.
 *
 * The module reads its configuration ONCE, at import, so every case stubs the environment and then
 * imports it fresh. That is also the property being pinned — reading per call would let a stale
 * `.env` change behaviour halfway through a session.
 *
 * Every case stubs `VITE_APP_LOG_LEVEL` explicitly, including the cases about its DEFAULT: Vite
 * loads the developer's own `.env` into `import.meta.env`, so a case that simply omits the variable
 * would assert against whatever happens to be in that file rather than against the fallback.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

/** Imports a fresh logger with the given environment. */
const loadLogger = (env: Record<string, unknown>) => {
    vi.resetModules();
    for (const [key, value] of Object.entries(env)) vi.stubEnv(key, value as string);
    return import('@/infrastructure/utils/logger');
};

let spies: Record<'debug' | 'info' | 'warn' | 'error', ReturnType<typeof vi.spyOn>>;

beforeEach(() => {
    spies = {
        debug: vi.spyOn(console, 'debug').mockImplementation(() => {}),
        info: vi.spyOn(console, 'info').mockImplementation(() => {}),
        warn: vi.spyOn(console, 'warn').mockImplementation(() => {}),
        error: vi.spyOn(console, 'error').mockImplementation(() => {})
    };
});

afterEach(() => {
    for (const spy of Object.values(spies)) spy.mockRestore();
    vi.unstubAllEnvs();
});

describe('scope filtering', () => {
    it('emits a debug message for a scope that was opted into', () =>
        loadLogger({ DEV: true, VITE_APP_LOG_SCOPES: 'router' }).then(({ logger }) => {
            logger.debug('router', 'navigating');

            expect(spies.debug).toHaveBeenCalled();
        }));

    it('drops a debug message for a scope that was not', () =>
        loadLogger({ DEV: true, VITE_APP_LOG_SCOPES: 'http' }).then(({ logger }) => {
            logger.debug('router', 'navigating');

            expect(spies.debug).not.toHaveBeenCalled();
        }));

    it('drops every scope when none are configured, which is the default', () =>
        loadLogger({ DEV: true, VITE_APP_LOG_SCOPES: '' }).then(({ logger }) => {
            logger.debug('router', 'navigating');
            logger.debug('http', 'requesting');

            expect(spies.debug).not.toHaveBeenCalled();
        }));

    it('enables every scope for `*`', () =>
        loadLogger({ DEV: true, VITE_APP_LOG_SCOPES: '*' }).then(({ logger }) => {
            logger.debug('router', 'a');
            logger.debug('demo', 'b');

            expect(spies.debug).toHaveBeenCalledTimes(2);
        }));

    it('tolerates spaces and trailing commas in the list', () =>
        loadLogger({ DEV: true, VITE_APP_LOG_SCOPES: ' router , http , ' }).then(({ logger }) => {
            logger.debug('router', 'a');
            logger.debug('http', 'b');

            expect(spies.debug).toHaveBeenCalledTimes(2);
        }));

    it('prefixes the scope, so a shared console says which area spoke', () =>
        loadLogger({ DEV: true, VITE_APP_LOG_SCOPES: 'router' }).then(({ logger }) => {
            logger.debug('router', 'navigating');

            expect(spies.debug).toHaveBeenCalledWith('[router]', 'navigating');
        }));

    it('never withholds a warning or an error for being out of scope', () =>
        loadLogger({ DEV: true, VITE_APP_LOG_SCOPES: '' }).then(({ logger }) => {
            // The one thing you always want to see is the thing that went wrong.
            logger.warn('careful');
            logger.error('broken');

            expect(spies.warn).toHaveBeenCalledWith('careful');
            expect(spies.error).toHaveBeenCalledWith('broken');
        }));
});

describe('level filtering', () => {
    it('drops everything below the configured level', () =>
        loadLogger({ DEV: true, VITE_APP_LOG_LEVEL: 'warn', VITE_APP_LOG_SCOPES: '*' }).then(
            ({ logger }) => {
                logger.debug('router', 'a');
                logger.info('router', 'b');
                logger.warn('c');
                logger.error('d');

                expect(spies.debug).not.toHaveBeenCalled();
                expect(spies.info).not.toHaveBeenCalled();
                expect(spies.warn).toHaveBeenCalled();
                expect(spies.error).toHaveBeenCalled();
            }
        ));

    it('silences all but errors at `error`', () =>
        loadLogger({ DEV: true, VITE_APP_LOG_LEVEL: 'error', VITE_APP_LOG_SCOPES: '*' }).then(
            ({ logger }) => {
                logger.warn('c');
                logger.error('d');

                expect(spies.warn).not.toHaveBeenCalled();
                expect(spies.error).toHaveBeenCalled();
            }
        ));

    it('defaults to debug in development', () =>
        loadLogger({ DEV: true, VITE_APP_LOG_LEVEL: '', VITE_APP_LOG_SCOPES: '*' }).then(
            ({ logger }) => {
                logger.debug('router', 'a');

                expect(spies.debug).toHaveBeenCalled();
            }
        ));

    it('defaults to warn in production, so a bundle carries no traces', () =>
        loadLogger({ DEV: false, VITE_APP_LOG_LEVEL: '', VITE_APP_LOG_SCOPES: '*' }).then(
            ({ logger }) => {
                logger.debug('router', 'a');
                logger.info('router', 'b');
                logger.warn('c');

                expect(spies.debug).not.toHaveBeenCalled();
                expect(spies.info).not.toHaveBeenCalled();
                expect(spies.warn).toHaveBeenCalled();
            }
        ));

    it('still reports errors in production, where Faro ships them', () =>
        loadLogger({ DEV: false, VITE_APP_LOG_LEVEL: '' }).then(({ logger }) => {
            logger.error('broken');

            expect(spies.error).toHaveBeenCalledWith('broken');
        }));

    it('falls back to the environment default for an unrecognised level', () =>
        loadLogger({ DEV: true, VITE_APP_LOG_LEVEL: 'lowd', VITE_APP_LOG_SCOPES: '*' }).then(
            ({ logger }) => {
                // A typo in an env var must not be the reason an error went unseen, so it degrades
                // to the default rather than to silence.
                logger.debug('router', 'a');
                logger.error('broken');

                expect(spies.debug).toHaveBeenCalled();
                expect(spies.error).toHaveBeenCalled();
            }
        ));
});

tests/unit/app/router/navigation.spec.ts.source:
/**
 * `loginContinueTo` — `src/app/router/navigation.ts`.
 *
 * One small function with one branch, and the branch is the whole point: a visitor bounced to login
 * should land back where they were aiming, EXCEPT when where they were aiming is an error page.
 * Sending someone back to `/en/error/403` after they successfully log in shows them the failure
 * again and hides the fact that logging in worked.
 *
 * It had no test of its own. The branch was reached only incidentally, by whichever guard spec
 * happened to pass a path through it, so which side was exercised depended on fixtures chosen for
 * other reasons — and the error-page side was never one of them.
 */
import { describe, expect, it } from 'vitest';
import { loginContinueTo, SIGN_IN_ROUTE_NAME, signInLocation } from '@/app/router/navigation';

describe('loginContinueTo', () => {
    it('remembers an ordinary target as a continue query', () => {
        expect(loginContinueTo('/en/cart', 'en')).toEqual({
            name: 'Login',
            params: { locale: 'en' },
            query: { continue: '/en/cart' }
        });
    });

    it('omits the continue query for an error page', () => {
        // Nobody wants to be sent back to the error they just recovered from.
        expect(loginContinueTo('/en/error/403/navigation.error-forbidden', 'en')).toEqual({
            name: 'Login',
            params: { locale: 'en' }
        });
    });

    it('carries no params at all when no locale is given', () => {
        // `undefined` rather than `{}`: an empty params object makes vue-router resolve a
        // locale-less `Login`, which the `/:locale` parent cannot match.
        expect(loginContinueTo('/cart')).toEqual({
            name: 'Login',
            params: undefined,
            query: { continue: '/cart' }
        });
    });

    it('omits params AND continue for an error page with no locale', () => {
        expect(loginContinueTo('/error/500')).toEqual({ name: 'Login', params: undefined });
    });

    it('matches on the word anywhere in the path, not only as a leading segment', () => {
        // The check is `includes`, so a nested error route is covered too. Pinned because
        // tightening it to `startsWith` would silently reintroduce the bounce-back.
        expect(loginContinueTo('/en/admin/error/500', 'en')).toEqual({
            name: 'Login',
            params: { locale: 'en' }
        });
    });
});

/**
 * `signInLocation` — the guard that keeps the shell working in a build with no sign-in route.
 *
 * The route name is a string the account module owns, so nothing type-checks it. With that module
 * deleted, an unguarded 401 pushes at a route that does not resolve, which aborts the navigation
 * and strands the visitor with no explanation.
 */
const routerWith = (names: string[]) => ({ hasRoute: (name: string) => names.includes(name) });

describe('signInLocation', () => {
    it('points at the sign-in route when this build has one', () => {
        expect(signInLocation(routerWith([SIGN_IN_ROUTE_NAME]), '/en/cart', 'en')).toEqual(
            loginContinueTo('/en/cart', 'en')
        );
    });

    it('falls back to Home when no sign-in route is registered', () => {
        expect(signInLocation(routerWith([]), '/en/cart', 'en')).toEqual({
            name: 'Home',
            params: { locale: 'en' }
        });
    });

    it('omits params in the fallback when no locale is given', () => {
        expect(signInLocation(routerWith([]), '/en/cart')).toEqual({
            name: 'Home',
            params: undefined
        });
    });
});

