/**
 * The axios binding around the toolkit's upload-progress state machine —
 * `src/infrastructure/composables/useUploadProgress.ts`.
 *
 * The state machine itself is the toolkit's and tested there. What is this app's, and therefore
 * tested here, is the axios shape: the `onUploadProgress` callback handed to the call, the 0–1
 * fraction it reports, and the "no file, no tracking" rule.
 */
import { describe, expect, it, afterEach, vi } from 'vitest';
import { nextTick } from 'vue';
import type { AxiosProgressEvent, AxiosRequestConfig } from 'axios';

import { useUploadProgress } from '@/infrastructure/composables/useUploadProgress.ts';

/**
 * Pulls the `onUploadProgress` callback out of the axios options `trackUpload` handed to `send`,
 * so a test can drive the progress bar without a real request.
 */
const progressCallbackOf = (options?: AxiosRequestConfig) => options?.onUploadProgress;

/** Fires that callback with a partial axios progress event. */
const reportProgress = (
    options: AxiosRequestConfig | undefined,
    event: Partial<AxiosProgressEvent>
) => progressCallbackOf(options)?.(event as AxiosProgressEvent);

/**
 * A file of an exact byte length, without allocating a real image: nothing here looks at the
 * contents, only at whether there is a file at all.
 */
const fileOfSize = (bytes: number, type = 'image/png') =>
    new File([new Uint8Array(bytes)], 'photo.png', { type });

afterEach(() => {
    vi.restoreAllMocks();
});

describe('useUploadProgress', () => {
    /**
     * `undefined` and `0` are different states — idle, versus a request that has started and sent
     * nothing yet — and `FormImageUpload` shows the bar for one and not the other.
     */
    it('starts idle rather than at zero', () => {
        expect(useUploadProgress().uploadProgress.value).toBeUndefined();
    });

    /**
     * The point of the whole helper: no file means no progress callback, so a plain field edit
     * does not flash the bar to 100% for a payload measured in bytes.
     */
    it('attaches no axios options at all when there is no file', () => {
        const { trackUpload } = useUploadProgress();
        const send = vi.fn().mockResolvedValue('done');

        return trackUpload(undefined, send).then(() => {
            // Called with no argument at all, which `send` reads as `options === undefined` just
            // the same — the point is that no progress callback is handed to the transport.
            expect(send).toHaveBeenCalledWith();
        });
    });

    it('attaches a progress callback when there is a file', () => {
        const { trackUpload } = useUploadProgress();
        const send = vi.fn().mockResolvedValue('done');

        return trackUpload(fileOfSize(1), send).then(() => {
            expect(progressCallbackOf(send.mock.calls[0][0])).toBeInstanceOf(Function);
        });
    });

    it('converts axios’ 0–1 fraction into a percentage while the call runs', () => {
        const { uploadProgress, trackUpload } = useUploadProgress();

        return trackUpload(fileOfSize(1), (options) => {
            reportProgress(options, { progress: 0.42 });
            expect(uploadProgress.value).toBe(42);
            return Promise.resolve();
        });
    });

    /**
     * `event.progress` is absent when the total size is unknown — a chunked or compressed
     * request. The bar stays at 0 instead of jumping about on a number that means nothing.
     */
    it('falls back to zero when the total size is unknown', () => {
        const { uploadProgress, trackUpload } = useUploadProgress();

        return trackUpload(fileOfSize(1), (options) => {
            reportProgress(options, { loaded: 1024 });
            expect(uploadProgress.value).toBe(0);
            return Promise.resolve();
        });
    });

    it('passes the result of the call straight through', () => {
        const { trackUpload } = useUploadProgress();

        return expect(trackUpload(fileOfSize(1), () => Promise.resolve('created'))).resolves.toBe(
            'created'
        );
    });

    it('returns to idle once the call resolves, not to zero', () => {
        const { uploadProgress, trackUpload } = useUploadProgress();

        return trackUpload(fileOfSize(1), (options) => {
            reportProgress(options, { progress: 1 });
            return Promise.resolve();
        }).then(() => {
            expect(uploadProgress.value).toBeUndefined();
        });
    });

    /**
     * The `finally` earning its keep: a failed upload must not leave the bar frozen mid-flight
     * for as long as the form stays open.
     */
    it('returns to idle when the call rejects, and re-throws', () => {
        const { uploadProgress, trackUpload } = useUploadProgress();

        return expect(
            trackUpload(fileOfSize(1), (options) => {
                reportProgress(options, { progress: 0.5 });
                return Promise.reject(new Error('upload failed'));
            })
        )
            .rejects.toThrow('upload failed')
            .then(() => {
                expect(uploadProgress.value).toBeUndefined();
            });
    });
});

tests/unit/app/router/router.spec.ts.source:
/**
 * Router wiring.
 *
 * `tests/unit/app/guards/authentications.spec.ts` proves `canAccess` decides correctly. This
 * proves the enforcement is actually *attached*, and that every route declares the requirement it
 * should — a route that quietly loses its `meta.access` is indistinguishable from a public one.
 *
 * Enforcement is therefore mocked here: what is under test is the router's own behaviour (the
 * locale redirect, the 404 catch-alls, the global auth restore, the error → redirect mapping) and
 * the declarations on the route records.
 */
import { afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import { signInLocation } from '@/app/router/navigation.ts';

const tryRestoreAuth = vi.fn(() => Promise.resolve());
// Returns nothing, i.e. "let the navigation through".
const enforceRouteAccess = vi.fn();

vi.mock('@/app/guards/authentications.ts', () => ({
    tryRestoreAuth: () => tryRestoreAuth(),
    enforceRouteAccess: (to: unknown) => enforceRouteAccess(to)
}));

vi.mock('@/infrastructure/stores/observability.ts', () => ({
    useObservabilityStore: () => ({ captureException: vi.fn(), track: vi.fn() }),
    analyticsEvents: {}
}));

/** Fresh router per test: it holds navigation state, and history is global. */
const loadRouter = () => {
    vi.resetModules();
    return import('@/app/router').then(({ default: router }) =>
        router
            .push('/')
            .then(() => router.isReady())
            .then(() => router)
    );
};

/**
 * Pay for the router's module graph once, outside any test's budget.
 *
 * `@/app/router` pulls in every view, and therefore Vuetify — the most expensive import in the suite.
 * `vi.resetModules()` in `loadRouter` clears the module registry but NOT Vite's transform cache,
 * so only the first import in this file actually transpiles anything; the rest are cheap.
 *
 * Left inside the first test, that one-off cost is charged to it, and under `--coverage` the
 * added instrumentation pushed it past the 5s default — a test that passed alone, passed in
 * `test:unit`, and failed only in `test:unit:coverage`. Warming it here keeps every real case on
 * the tight default budget, which is where a genuine hang should still be caught.
 */
beforeAll(async () => {
    await import('@/app/router');
}, 60_000);

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    globalThis.history.replaceState({}, '', '/');
});

afterEach(() => {
    vi.unstubAllEnvs();
});

describe('locale handling', () => {
    it('redirects the bare root to the locale-prefixed home', () =>
        loadRouter().then((router) => {
            expect(router.currentRoute.value.name).toBe('Home');
            expect(router.currentRoute.value.params.locale).toBeTruthy();
        }));
});

describe('unknown routes', () => {
    it('sends an unknown path under a locale to the 404 error page, keeping the locale', () =>
        loadRouter().then((router) =>
            router.push('/en/this-does-not-exist').then(() => {
                expect(router.currentRoute.value.name).toBe('Error');
                expect(router.currentRoute.value.params.status).toBe('404');
                expect(router.currentRoute.value.params.locale).toBe('en');
            })
        ));

    // A single unknown segment is indistinguishable from a locale: `/:locale` matches it, the
    // empty child matches the rest, and `localeChoice` then rewrites the unsupported locale to
    // the default one. So `/nonsense` lands on Home, not on the 404 page — the top-level
    // `/:catchAll(.*)` route is only reachable for paths that cannot be read as a locale at all.
    // Asserted here so the behaviour is a decision on record rather than a surprise.
    it('treats a single unknown segment as a locale and lands on home', () =>
        loadRouter().then((router) =>
            router.push('/nonsense').then(() => {
                expect(router.currentRoute.value.name).toBe('Home');
                expect(router.currentRoute.value.params.locale).not.toBe('nonsense');
            })
        ));

    /**
     * A deep unknown path is caught by the LOCALE-scoped catch-all, not the top-level one.
     *
     * `/:locale` matches a single segment, so `/a/b/c` reads as locale `a` with `b/c` left for
     * the children — where `:catchAll(.*)` takes it. Together with the case above, this is what
     * makes the top-level `/:catchAll(.*)` route unreachable: every path is either `/`, or has a
     * first segment that `/:locale` accepts.
     *
     * Recorded rather than deleted, because "unreachable" is a claim about the route table that
     * only holds while `/:locale` stays a single-segment param — and this test is what would fail
     * if that changed.
     */
    it('sends a deep unknown path to the locale-scoped 404', () =>
        loadRouter().then((router) =>
            router.push('/en/nope/nope/nope').then(() => {
                expect(router.currentRoute.value.name).toBe('Error');
                expect(router.currentRoute.value.params.status).toBe('404');
                expect(router.currentRoute.value.params.message).toBe('error-page.not-found');
                expect(router.currentRoute.value.params.locale).toBe('en');
            })
        ));
});

/**
 * The shop's prose pages — one component, four route records generated from a list.
 *
 * Worth pinning because the NAME is computed (`'Static' + page[0].toUpperCase() + page.slice(1)`)
 * and every navigation to these pages is by name. An off-by-one in that expression produces
 * `StaticAbout` → `Staticbout`, which TypeScript cannot see and which fails only as a dead link.
 */
describe('static prose pages', () => {
    it.each([
        ['about', 'StaticAbout'],
        ['faq', 'StaticFaq'],
        ['terms', 'StaticTerms'],
        ['privacy', 'StaticPrivacy']
    ])('serves /%s as the route named %s', (page, name) =>
        loadRouter().then((router) =>
            router.push(`/en/${page}`).then(() => {
                expect(router.currentRoute.value.name).toBe(name);
                // The one prop that tells the shared component which dictionary to render.
                expect(router.currentRoute.value.matched.at(-1)?.props.default).toEqual({ page });
            })
        )
    );
});

describe('global auth restore', () => {
    it('runs on the initial navigation', () =>
        loadRouter().then(() => {
            expect(tryRestoreAuth).toHaveBeenCalled();
        }));

    it('runs again on every subsequent navigation', () =>
        loadRouter().then((router) => {
            const callsAfterBoot = tryRestoreAuth.mock.calls.length;

            return router.push('/en/playground').then(() => {
                expect(tryRestoreAuth.mock.calls.length).toBeGreaterThan(callsAfterBoot);
            });
        }));
});

describe('access enforcement', () => {
    it('runs on every navigation, public routes included', () =>
        loadRouter().then((router) =>
            router.push('/en/playground').then(() => {
                // Enforcement is global, so it is reached even where it has nothing to enforce.
                // That is the point: a route cannot opt out of being checked by omission.
                expect(enforceRouteAccess).toHaveBeenCalled();
            })
        ));

    it('runs only after the auth restore has settled', () =>
        loadRouter().then((router) => {
            const order: string[] = [];
            tryRestoreAuth.mockImplementationOnce(() =>
                Promise.resolve().then(() => {
                    order.push('restore');
                })
            );
            enforceRouteAccess.mockImplementationOnce(() => {
                order.push('enforce');
            });

            // Reversed, an authenticated visitor who reloads is bounced to login on every hit.
            return router.push('/en/playground').then(() => {
                expect(order).toEqual(['restore', 'enforce']);
            });
        }));

    /*
     * The per-route access DECLARATIONS moved to `src/modules/<name>/tests/routes.spec.ts`.
     *
     * They were a table of domain paths here, which meant deleting a domain broke a platform
     * spec about the router shell. What belongs at this level is that enforcement is attached
     * and correctly ordered — asserted above using the two routes the shell owns itself.
     */
});

/**
 * Pushes a route whose guard throws the given error, then lets `onError`'s redirect settle.
 *
 * Waits for the router to actually leave the starting route rather than for a fixed number of
 * ticks: `onError` handles the failure and issues a *second* navigation, which has its own guard
 * chain to run, so how many microtasks that takes is an implementation detail of the guards.
 */
const failNavigationWith = (error: Error) =>
    loadRouter().then((router) =>
        /*
         * Settle somewhere that is NOT Home before failing anything.
         *
         * The wait below is "did we leave `before`", and one of the redirect targets — the 401
         * fallback when this build ships no sign-in route — IS Home. Starting on Home made a
         * correct redirect indistinguishable from no redirect at all, and the helper reported
         * `still on /en` for behaviour that was right.
         */
        router.push('/en/playground').then(() => {
            const before = router.currentRoute.value.fullPath;
            enforceRouteAccess.mockImplementationOnce(() => {
                throw error;
            });
            return router
                .push('/en')
                .catch(() => {})
                .then(() =>
                    // A thrown Error rather than `expect`, so this reads as a wait condition in a
                    // helper rather than as an assertion outside a test block.
                    vi.waitFor(() => {
                        if (router.currentRoute.value.fullPath === before)
                            throw new Error(`still on ${before}`);
                    })
                )
                .then(() => router);
        })
    );

describe('onError redirects', () => {
    it('sends a 401 to the sign-in page, remembering where the user was going', () =>
        failNavigationWith(Object.assign(new Error('nope'), { status: 401 })).then((router) => {
            /*
             * Which route that is belongs to whichever module provides sign-in, so the expectation
             * is computed from `signInLocation` rather than spelled `'Login'` here. What this pins
             * is the WIRING — that a 401 goes through that helper at all — while
             * `navigation.spec.ts` covers both of the helper's own branches directly.
             */
            expect(router.currentRoute.value.name).toBe(
                signInLocation(router, '/en/playground', 'en').name
            );
            // The point of the 401 branch: a recoverable status must not dead-end on the error
            // page, which is where every other status goes.
            expect(router.currentRoute.value.name).not.toBe('Error');
        }));

    it('sends a 403 to the forbidden error page', () =>
        failNavigationWith(Object.assign(new Error('nope'), { status: 403 })).then((router) => {
            expect(router.currentRoute.value.name).toBe('Error');
            expect(router.currentRoute.value.params.status).toBe('403');
            // The reason 403 keeps a branch of its own: "you may not see this" is a different
            // thing to tell someone than whatever `error.message` happened to hold ('nope').
            expect(router.currentRoute.value.params.message).toBe('navigation.error-forbidden');
        }));

    it('shows the error’s own message for other client statuses', () =>
        failNavigationWith(Object.assign(new Error('teapot'), { status: 418 })).then((router) => {
            expect(router.currentRoute.value.params.status).toBe('418');
            expect(router.currentRoute.value.params.message).toBe('teapot');
        }));

    it('collapses a 5xx status to a plain 500', () =>
        /*
         * The `status !== undefined && status < 500` guard needs a DEFINED status at or above 500 to
         * be meaningful: with an absent one both halves are false either way, so 401/403/418 and the
         * no-status case together still cannot tell `&&` from `||`, nor a fixed `true` from the real
         * condition. A 503 is the case that does.
         *
         * Collapsing is deliberate — the flavour of a server-side failure is not the visitor's
         * business, and the error page has one 500 screen.
         */
        failNavigationWith(Object.assign(new Error('gateway'), { status: 503 })).then((router) => {
            expect(router.currentRoute.value.params.status).toBe('500');
        }));

    it('treats an error with no status as a 500', () =>
        failNavigationWith(new Error('boom')).then((router) => {
            expect(router.currentRoute.value.name).toBe('Error');
            expect(router.currentRoute.value.params.status).toBe('500');
        }));
});

/**
 * Navigation tracing, which `utils/logger.ts` gates on the `router` scope.
 *
 * The logger resolves its level and scopes once at module scope, so the environment has to be
 * stubbed BEFORE the import — which is why these cases load the router themselves rather than
 * reusing `loadRouter`.
 *
 * Both directions are asserted. A trace that never appears when asked for is as wrong as one that
 * appears when it was not, and only the second is visible by accident.
 */
/** Loads a fresh router with the log scopes stubbed BEFORE import, since they are read once there. */
const loadRouterWithDebug = (enabled: boolean) => {
    vi.resetModules();
    vi.stubEnv('DEV', true);
    vi.stubEnv('VITE_APP_LOG_LEVEL', 'debug');
    vi.stubEnv('VITE_APP_LOG_SCOPES', enabled ? 'router' : '');
    return import('@/app/router').then(({ default: router }) =>
        router
            .push('/')
            .then(() => router.isReady())
            .then(() => router)
    );
};

/** Every argument of every recorded call, flattened, so a prefixed message still matches. */
const debugText = (spy: { mock: { calls: unknown[][] } }) =>
    spy.mock.calls.map((call) => call.map(String).join(' ')).join('\n');

describe('router navigation tracing', () => {
    it('logs each navigation when the router scope is on', () => {
        const debugSpy = vi.spyOn(console, 'debug').mockImplementation(() => {});

        return loadRouterWithDebug(true)
            .then((router) => router.push('/en/playground'))
            .then(() => {
                // The logger prefixes its own scope, so the assertion is on the whole line rather
                // than on the first argument.
                expect(debugText(debugSpy)).toContain('[router]');
                expect(debugText(debugSpy)).toContain('Navigating');
                debugSpy.mockRestore();
            });
    });

    it('stays silent when the router scope is off', () => {
        const debugSpy = vi.spyOn(console, 'debug').mockImplementation(() => {});

        return loadRouterWithDebug(false)
            .then((router) => router.push('/en/playground'))
            .then(() => {
                // Scoped to the navigation line rather than asserting console silence outright:
                // other modules may log on boot, and a blanket assertion would fail for reasons
                // that say nothing about the router.
                expect(debugText(debugSpy)).not.toContain('Navigating');
                debugSpy.mockRestore();
            });
    });

    it('reports a navigation failure when the router scope is on', () => {
        const debugSpy = vi.spyOn(console, 'debug').mockImplementation(() => {});

        return loadRouterWithDebug(true)
            .then((router) => {
                enforceRouteAccess.mockImplementationOnce(() => {
                    throw new Error('boom');
                });
                return router.push('/en/playground').catch(() => router);
            })
            .then(() =>
                vi.waitFor(() => {
                    if (!debugText(debugSpy).includes('page error'))
                        throw new Error('no page error trace yet');
                })
            )
            .then(() => {
                expect(debugText(debugSpy)).toContain('page error');
                debugSpy.mockRestore();
            });
    });
});

src/modules/realtime/tests/useRealtimeOb.source:
/**
 * Unit tests for the SSE composable behind the observability dashboard.
 *
 * `createSseClient` is mocked rather than driven through a real `EventSource`: what this file owns
 * is the wiring — which url is opened, which store action each event name reaches, and that the
 * module-level singleton is torn down before a second connection replaces it. The transport itself
 * is `tests/unit/infrastructure/createSseClient.spec.ts`.
 *
 * Every case re-imports the module through `vi.resetModules()`, because `activeClient` lives at
 * module scope: without a fresh module a test would inherit the previous test's open connection and
 * the reconnect assertions would pass for the wrong reason.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import type { SseClientCallbacks } from '@/infrastructure/createSseClient';
import type { MetricsSnapshotEvent, SseEventName } from '@types';

const close = vi.fn();

/**
 * The parameters are declared even though the body ignores them: `vi.fn(() => …)` types its
 * `mock.calls` as an empty tuple, so every assertion on what the composable PASSED — the url, the
 * event names, the callbacks — would be a type error rather than a check.
 */
const createSseClient = vi.fn(
    (_url?: string, _eventNames?: readonly SseEventName[], _callbacks?: SseClientCallbacks) => ({
        close
    })
);

vi.mock('@/infrastructure/createSseClient', () => ({
    createSseClient: (...parameters: unknown[]) =>
        createSseClient(...(parameters as Parameters<typeof createSseClient>))
}));

/** Minimal payload accepted by every metrics event on the stream. */
const makeEvent = (timestamp: string): MetricsSnapshotEvent => ({
    timestamp,
    uptimeSeconds: 60,
    memory: { rss: 1, heapUsed: 1, heapTotal: 2, external: 0 },
    http: { totalRequests: 10, totalErrors: 0 },
    realtime: { sseClients: 1 }
});

/**
 * Imports the composable and its store fresh, so the module-level `activeClient` starts undefined.
 *
 * @returns The composable factory and the store hook from the same module graph.
 */
const loadComposable = async () => {
    vi.resetModules();
    const [{ useRealtimeObservability }, { useRealtimeObservabilityStore }] = await Promise.all([
        import('@/modules/realtime/useRealtimeObservability'),
        import('@/modules/realtime/realtimeObservability')
    ]);
    return { useRealtimeObservability, useRealtimeObservabilityStore };
};

/** The callbacks handed to the last `createSseClient` call. */
const lastCallbacks = () => createSseClient.mock.calls.at(-1)?.[2] as SseClientCallbacks;

describe('useRealtimeObservability', () => {
    beforeEach(() => {
        setActivePinia(createPinia());
        vi.clearAllMocks();
    });

    afterEach(() => {
        vi.unstubAllEnvs();
    });

    describe('connect', () => {
        it('opens the endpoint from VITE_API_SSE, for every contract event name', async () => {
            vi.stubEnv('VITE_API_SSE', 'https://api.example.com/observability/events');
            const { useRealtimeObservability } = await loadComposable();

            useRealtimeObservability().connect();

            expect(createSseClient).toHaveBeenCalledWith(
                'https://api.example.com/observability/events',
                [
                    'observability.heartbeat',
                    'observability.metrics.snapshot',
                    'observability.metrics.updated'
                ],
                expect.anything()
            );
        });

        it('falls back to the local dev endpoint when VITE_API_SSE is unset', async () => {
            vi.stubEnv('VITE_API_SSE', undefined);
            const { useRealtimeObservability } = await loadComposable();

            useRealtimeObservability().connect();

            expect(createSseClient.mock.calls[0]?.[0]).toBe(
                'http://localhost:3000/observability/events'
            );
        });

        it('reports connecting before the transport answers', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();

            useRealtimeObservability().connect();

            expect(store.status).toBe('connecting');
        });

        it('closes the previous client so a second connect cannot leave two streams open', async () => {
            const { useRealtimeObservability } = await loadComposable();
            const { connect } = useRealtimeObservability();

            connect();
            expect(close).not.toHaveBeenCalled();

            connect();
            expect(close).toHaveBeenCalledTimes(1);
            expect(createSseClient).toHaveBeenCalledTimes(2);
        });
    });

    describe('transport callbacks', () => {
        it('reports open once the stream is established', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();

            useRealtimeObservability().connect();
            lastCallbacks().onOpen?.();

            expect(store.status).toBe('open');
        });

        it('records both the error status and a message the dashboard can show', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();

            useRealtimeObservability().connect();
            lastCallbacks().onError?.(new Event('error'));

            expect(store.status).toBe('error');
            expect(store.lastError).toBe('SSE connection error');
        });
    });

    describe('event routing', () => {
        it('sends a snapshot to setSnapshot and appends one snapshot entry', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();
            const payload = makeEvent('2026-01-01T00:00:00.000Z');

            useRealtimeObservability().connect();
            lastCallbacks().onEvent?.('observability.metrics.snapshot', payload);

            expect(store.latestSnapshot).toEqual(payload);
            // The early return is what keeps a snapshot out of the heartbeat branch below it
            expect(store.latestHeartbeatAt).toBeUndefined();
            expect(store.latestUpdate).toBeUndefined();
            expect(store.entries).toEqual([
                {
                    id: 'snapshot-2026-01-01T00:00:00.000Z',
                    kind: 'snapshot',
                    timestamp: '2026-01-01T00:00:00.000Z',
                    payload
                }
            ]);
        });

        it('sends an update to setUpdate and appends one update entry', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();
            const payload = makeEvent('2026-01-01T00:01:00.000Z');

            useRealtimeObservability().connect();
            lastCallbacks().onEvent?.('observability.metrics.updated', payload);

            expect(store.latestUpdate).toEqual(payload);
            expect(store.latestSnapshot).toBeUndefined();
            expect(store.latestHeartbeatAt).toBeUndefined();
            expect(store.entries).toEqual([
                {
                    id: 'update-2026-01-01T00:01:00.000Z',
                    kind: 'update',
                    timestamp: '2026-01-01T00:01:00.000Z',
                    payload
                }
            ]);
        });

        it('treats anything else as a heartbeat', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();
            const payload = makeEvent('2026-01-01T00:02:00.000Z');

            useRealtimeObservability().connect();
            lastCallbacks().onEvent?.('observability.heartbeat', payload);

            expect(store.latestHeartbeatAt).toBe('2026-01-01T00:02:00.000Z');
            expect(store.latestSnapshot).toBeUndefined();
            expect(store.latestUpdate).toBeUndefined();
            expect(store.entries).toEqual([
                {
                    id: 'heartbeat-2026-01-01T00:02:00.000Z',
                    kind: 'heartbeat',
                    timestamp: '2026-01-01T00:02:00.000Z',
                    payload
                }
            ]);
        });

        it('keeps the feed in arrival order across event kinds', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();

            useRealtimeObservability().connect();
            const callbacks = lastCallbacks();
            callbacks.onEvent?.(
                'observability.metrics.snapshot',
                makeEvent('2026-01-01T00:00:00.000Z')
            );
            callbacks.onEvent?.('observability.heartbeat', makeEvent('2026-01-01T00:00:30.000Z'));
            callbacks.onEvent?.(
                'observability.metrics.updated',
                makeEvent('2026-01-01T00:01:00.000Z')
            );

            expect(store.entries.map((entry) => entry.kind)).toEqual([
                'snapshot',
                'heartbeat',
                'update'
            ]);
        });
    });

    describe('disconnect', () => {
        it('closes the stream and reports closed', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();
            const { connect, disconnect } = useRealtimeObservability();

            connect();
            disconnect();

            expect(close).toHaveBeenCalledTimes(1);
            expect(store.status).toBe('closed');
        });

        it('is safe with no connection open, and does not close a stream twice', async () => {
            const { useRealtimeObservability, useRealtimeObservabilityStore } =
                await loadComposable();
            const store = useRealtimeObservabilityStore();
            const { connect, disconnect } = useRealtimeObservability();

            disconnect();
            expect(close).not.toHaveBeenCalled();
            expect(store.status).toBe('closed');

            connect();
            disconnect();
            disconnect();
            expect(close).toHaveBeenCalledTimes(1);
        });

        it('reconnects after a disconnect without closing the released client again', async () => {
            const { useRealtimeObservability } = await loadComposable();
            const { connect, disconnect } = useRealtimeObservability();

            connect();
            disconnect();
            connect();

            expect(close).toHaveBeenCalledTimes(1);
            expect(createSseClient).toHaveBeenCalledTimes(2);
        });
    });

    it('exposes the store state alongside the controls', async () => {
        const { useRealtimeObservability, useRealtimeObservabilityStore } = await loadComposable();
        const store = useRealtimeObservabilityStore();
        const { status, latestSnapshot, latestUpdate, latestHeartbeatAt, entries, lastError } =
            useRealtimeObservability();

        store.setStatus('open');
        store.setError('nope');

        expect(status.value).toBe('open');
        expect(lastError.value).toBe('nope');
        expect(latestSnapshot.value).toBeUndefined();
        expect(latestUpdate.value).toBeUndefined();
        expect(latestHeartbeatAt.value).toBeUndefined();
        expect(entries.value).toEqual([]);
    });
});

tests/unit/infrastructure/http/httpRefre.source:
/**
 * The 401 → refresh → replay flow, driven through the real interceptor chain.
 *
 * This is the one piece of client logic where a bug is both invisible to types and invisible to
 * the e2e suite: a broken refresh does not throw, it just logs the user out at some later moment.
 *
 * It is therefore tested against a real HTTP server (MSW's node interceptor) rather than a
 * stubbed axios adapter. The whole point is that `instance.interceptors.response` runs, that the
 * *replay* goes back through the same instance, and that `_dontRetry` actually stops the second
 * round — none of which a hand-rolled adapter would reproduce.
 *
 * `tests/unit/infrastructure/http/http.spec.ts` covers the error-normalisation side of the same module with
 * plain unit stubs; the two are complementary.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { setupServer } from 'msw/node';
import { http, HttpResponse } from 'msw';
import { createPinia, setActivePinia } from 'pinia';

const API = 'http://api.test';

/** Requests seen by the server, in order, as `METHOD path` plus the bearer token sent. */
let requestLog: { route: string; authorization?: string }[] = [];

/** Number of times /account/refresh may still succeed; anything beyond answers 401. */
let refreshBudget = 1;

/** Whether the protected route accepts the token it is given. */
let protectedAccepts = false;

/** Mirrors `refreshExcludedPaths` in `src/infrastructure/http/index.ts`. */
const EXCLUDED_PATHS = [
    '/account/login',
    '/account/signup',
    '/account/reset',
    '/account/reset-confirm',
    '/account/logout-all'
];

/**
 * The same exclusion, spelled absolutely. Generated clients send relative urls, but a caller
 * passing an absolute one must get the same treatment or the exclusion silently stops applying.
 */
const ABSOLUTE_EXCLUDED_URL = 'https://api.example.com/account/login';

const server = setupServer(
    http.get(`${API}/account/refresh`, ({ request }) => {
        requestLog.push({
            route: 'GET /account/refresh',
            authorization: request.headers.get('authorization') ?? undefined
        });
        if (refreshBudget <= 0)
            return HttpResponse.json(
                { success: false, status: 401, message: 'Unauthorized', errors: ['Unauthorized'] },
                { status: 401 }
            );
        refreshBudget -= 1;
        return HttpResponse.json({ success: true, status: 200, data: { token: 'fresh-token' } });
    }),

    http.get(`${API}/orders`, ({ request }) => {
        const authorization = request.headers.get('authorization') ?? undefined;
        requestLog.push({ route: 'GET /orders', authorization });
        if (protectedAccepts && authorization === 'Bearer fresh-token')
            return HttpResponse.json({ success: true, status: 200, data: { items: [] } });
        return HttpResponse.json(
            { success: false, status: 401, message: 'Unauthorized', errors: ['Unauthorized'] },
            { status: 401 }
        );
    }),

    // Every path on the refresh-exclusion list, plus one spelled as an absolute URL. Each
    // answers 401 as a normal business outcome (wrong password, expired reset link, session
    // already invalidated) — the case the exclusion list exists for.
    ...[...EXCLUDED_PATHS, ABSOLUTE_EXCLUDED_URL].map((path) =>
        http.post(path.startsWith('http') ? path : `${API}${path}`, ({ request }) => {
            requestLog.push({ route: `POST ${new URL(request.url).pathname}` });
            return HttpResponse.json(
                {
                    success: false,
                    status: 401,
                    message: 'Unauthorized',
                    errors: ['Bad credentials']
                },
                { status: 401 }
            );
        })
    )
);

/**
 * Imports the http plugin fresh, with the API base URL stubbed.
 *
 * The module builds its axios instance and registers its interceptors at import time, so the
 * env has to be in place first and the registry has to be reset between tests — otherwise the
 * interceptors stack up across cases.
 */
const loadHttp = () => {
    vi.resetModules();
    vi.stubEnv('VITE_API_URL', API);
    return import('@/infrastructure/http');
};

beforeAll(() => server.listen({ onUnhandledRequest: 'error' }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

beforeEach(() => {
    setActivePinia(createPinia());
    requestLog = [];
    refreshBudget = 1;
    protectedAccepts = false;
    vi.unstubAllEnvs();
});

describe('401 refresh flow', () => {
    it('refreshes once and replays the original request with the new token', () => {
        protectedAccepts = true;

        return loadHttp()
            .then(({ orvalMutator }) =>
                orvalMutator<{ data: { items: unknown[] } }>({ url: '/orders', method: 'GET' })
            )
            .then((result) => {
                expect(result.data.items).toEqual([]);
                expect(requestLog.map(({ route }) => route)).toEqual([
                    'GET /orders',
                    'GET /account/refresh',
                    'GET /orders'
                ]);
                expect(requestLog.at(-1)?.authorization).toBe('Bearer fresh-token');
            });
    });

    it('stores the refreshed token on the profile, so later calls carry it', () => {
        protectedAccepts = true;

        return loadHttp().then(({ orvalMutator, getAccessToken }) =>
            orvalMutator({ url: '/orders', method: 'GET' }).then(() => {
                expect(getAccessToken()).toBe('fresh-token');
            })
        );
    });

    it('does not retry a second time when the replay also fails', () =>
        // protectedAccepts stays false: the replayed request 401s as well.
        loadHttp()
            .then(({ orvalMutator }) =>
                expect(orvalMutator({ url: '/orders', method: 'GET' })).rejects.toMatchObject({
                    status: 401
                })
            )
            .then(() => {
                // Exactly one refresh and exactly two /orders calls — `_dontRetry` stopped the
                // loop.
                expect(
                    requestLog.filter(({ route }) => route === 'GET /account/refresh')
                ).toHaveLength(1);
                expect(requestLog.filter(({ route }) => route === 'GET /orders')).toHaveLength(2);
            }));

    it('rejects with the original error when the refresh itself fails', () => {
        refreshBudget = 0;

        return loadHttp()
            .then(({ orvalMutator }) =>
                expect(orvalMutator({ url: '/orders', method: 'GET' })).rejects.toMatchObject({
                    success: false,
                    status: 401
                })
            )
            .then(() => {
                expect(requestLog.filter(({ route }) => route === 'GET /orders')).toHaveLength(1);
            });
    });

    /**
     * Each excluded endpoint answers 401 as a normal business outcome, so refreshing there turns
     * a clean error message into an extra round trip and — when the refresh also fails — a
     * misleading session-expired state.
     *
     * Driven through `orvalMutator` against the real interceptor chain, and asserted on the
     * server's own request log — the only place a refresh attempt is observable without
     * mocking the very code under test.
     */
    it.each([...EXCLUDED_PATHS, ABSOLUTE_EXCLUDED_URL])(
        'never attempts a refresh for a 401 from %s',
        (url) =>
            loadHttp()
                .then(({ orvalMutator }) =>
                    expect(orvalMutator({ url, method: 'POST', data: {} })).rejects.toMatchObject({
                        status: 401
                    })
                )
                .then(() => {
                    // The endpoint itself was reached...
                    expect(requestLog.some(({ route }) => route.startsWith('POST '))).toBe(true);
                    // ...and no refresh was attempted off the back of its 401.
                    expect(requestLog.some(({ route }) => route === 'GET /account/refresh')).toBe(
                        false
                    );
                })
    );
});

tests/unit/infrastructure/http/httpValid.source:
/**
 * `orvalMutator`'s contract-validation layer (`VITE_VALIDATE_RESPONSES`), tested against a real
 * HTTP server the same way `httpRefresh.spec.ts` tests the refresh flow — a stubbed axios
 * adapter wouldn't exercise the interceptor chain the mutator actually runs through.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it, vi } from 'vitest';
import { setupServer } from 'msw/node';
import { http, HttpResponse } from 'msw';
import { createPinia, setActivePinia } from 'pinia';

const API = 'http://api.test';

const server = setupServer();

/**
 * Load a fresh `@/infrastructure/http` and wire the enabled modules' response schemas into it, exactly as
 * `src/main.ts` does at boot.
 *
 * The registration is not optional dressing. Every domain row — `/account` included — lives in
 * `src/modules/<name>/responseSchemas.ts` now, and `vi.resetModules()` gives each test a brand new
 * `responseSchemaMap` holding only the handful of core rows. Skip the wiring and
 * `resolveResponseSchema` returns `undefined`, validation quietly no-ops, and the two tests that
 * assert a *throw* fail — which is how this helper earned its existence.
 */
const loadHttp = () => {
    vi.resetModules();
    vi.stubEnv('VITE_API_URL', API);
    return Promise.all([
        import('@/infrastructure/http'),
        import('@/infrastructure/http/responseSchemaMap'),
        import('@/kernel/registry'),
        import('@/modules')
    ]).then(
        ([
            httpModule,
            { registerResponseSchemas },
            { collectModuleResponseSchemas },
            { enabledModules }
        ]) => {
            registerResponseSchemas(collectModuleResponseSchemas(enabledModules));
            return httpModule;
        }
    );
};

beforeAll(() => server.listen({ onUnhandledRequest: 'error' }));
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

beforeEach(() => {
    setActivePinia(createPinia());
    vi.unstubAllEnvs();
});

describe('orvalMutator contract validation', () => {
    it('is off by default inside Vitest, even though DEV is true (MODE is "test")', () => {
        // A response that violates GetAccountResponse (missing required `email`) — if
        // validation ran, this would throw.
        server.use(
            http.get(`${API}/account`, () =>
                HttpResponse.json({ success: true, status: 200, message: 'ok', data: { id: '1' } })
            )
        );
        return loadHttp().then(({ orvalMutator }) =>
            expect(orvalMutator({ url: '/account', method: 'GET' })).resolves.toMatchObject({
                data: { id: '1' }
            })
        );
    });

    it('resolves normally when VITE_VALIDATE_RESPONSES=true and the response satisfies its schema', () => {
        server.use(
            http.get(`${API}/account`, () =>
                HttpResponse.json({
                    success: true,
                    status: 200,
                    message: 'ok',
                    data: { id: '1', email: 'a@b.com', username: 'alice' }
                })
            )
        );
        vi.stubEnv('VITE_VALIDATE_RESPONSES', 'true');
        return loadHttp().then(({ orvalMutator }) =>
            expect(orvalMutator({ url: '/account', method: 'GET' })).resolves.toMatchObject({
                data: { id: '1', email: 'a@b.com', username: 'alice' }
            })
        );
    });

    it('throws a contract error when VITE_VALIDATE_RESPONSES=true and a required field is missing', () => {
        server.use(
            http.get(`${API}/account`, () =>
                HttpResponse.json({ success: true, status: 200, message: 'ok', data: { id: '1' } })
            )
        );
        vi.stubEnv('VITE_VALIDATE_RESPONSES', 'true');
        return loadHttp().then(({ orvalMutator }) =>
            expect(orvalMutator({ url: '/account', method: 'GET' })).rejects.toThrow(
                /\[contract] response for GET \/account does not match the OpenAPI schema/
            )
        );
    });

    it('throws a contract error when the response carries an undeclared field (strict schema)', () => {
        server.use(
            http.get(`${API}/account`, () =>
                HttpResponse.json({
                    success: true,
                    status: 200,
                    message: 'ok',
                    data: {
                        id: '1',
                        email: 'a@b.com',
                        username: 'alice',
                        // Not part of the OpenAPI schema — the exact class of bug (over-serialization)
                        // this validation exists to catch.
                        passwordHash: 'should-never-be-serialized'
                    }
                })
            )
        );
        vi.stubEnv('VITE_VALIDATE_RESPONSES', 'true');
        return loadHttp().then(({ orvalMutator }) =>
            expect(orvalMutator({ url: '/account', method: 'GET' })).rejects.toThrow(/\[contract]/)
        );
    });

    it('never validates when VITE_VALIDATE_RESPONSES=false, even for a non-conformant response', () => {
        server.use(
            http.get(`${API}/account`, () =>
                HttpResponse.json({ success: true, status: 200, message: 'ok', data: { id: '1' } })
            )
        );
        vi.stubEnv('VITE_VALIDATE_RESPONSES', 'false');
        return loadHttp().then(({ orvalMutator }) =>
            expect(orvalMutator({ url: '/account', method: 'GET' })).resolves.toMatchObject({
                data: { id: '1' }
            })
        );
    });

    it('fails open (warns, does not throw) for a route absent from the schema map', () => {
        server.use(
            http.get(`${API}/not-a-real-route`, () => HttpResponse.json({ anything: 'goes' }))
        );
        vi.stubEnv('VITE_VALIDATE_RESPONSES', 'true');
        const warnSpy = vi.spyOn(console, 'warn').mockImplementation(() => {
            /* no-op */
        });
        return loadHttp()
            .then(({ orvalMutator }) =>
                expect(
                    orvalMutator({ url: '/not-a-real-route', method: 'GET' })
                ).resolves.toMatchObject({ anything: 'goes' })
            )
            .then(() => {
                expect(warnSpy).toHaveBeenCalledWith(
                    expect.stringContaining('no response schema mapped for GET /not-a-real-route')
                );
                warnSpy.mockRestore();
            });
    });
});

tests/unit/app/AppNavigation.spec.ts.source:
/**
 * App navigation.
 *
 * Beyond rendering, this pins the property that makes the menu trustworthy: an entry is shown
 * exactly when the router would let the visitor enter the route it points at. The nav reads
 * `meta.access` off the resolved route rather than carrying its own visibility flags, so the two
 * cannot drift — and these cases are what would catch it if someone reintroduced a flag.
 *
 * ── Why the modules here are invented ────────────────────────────────────────────────────────
 * `AppNavigation` builds its list from `collectModuleNavigation(enabledModules)`. Asserting
 * against the REAL registry would mean naming `products`, `cart`, `admin`… in a platform spec —
 * the exact coupling the manifest removed from `src/`, moved into `tests/`. Deleting a domain
 * would then break a test that is not about that domain at all (see `docs/theory/modules.md`,
 * "Deleting a domain").
 *
 * So `@/modules` is mocked with three throwaway domains covering the three visibility classes.
 * What is under test is the mechanism — filter by the resolved route's `meta.access`, order by
 * `order` — and the mechanism is what breaks. That every real module's entry points at a route it
 * actually declares is a separate, registry-driven invariant: `tests/cross-cutting/registry.spec.ts`.
 */
import { beforeEach, describe, it, expect, vi } from 'vitest';
import { mount } from '@vue/test-utils';
import { ref } from 'vue';
import { createPinia } from 'pinia';
import AppNavigation from '@/app/components/AppNavigation.vue';
import vuetify from '@/ui/vuetify';
import type { RouteAccess } from '@/app/guards/authentications';

const session = {
    isAuth: ref(false),
    isAdmin: ref(false),
    viewer: ref<{ email: string } | undefined>(undefined)
};

/**
 * Which of the auth routes this build ships.
 *
 * The shell addresses `Login` and `Signup` by name — strings the account module owns and nothing
 * type-checks — so it asks `router.hasRoute` before offering either. Flipping this to `false` is
 * the "no account module in this build" case.
 */
const registeredRoutes = ref<string[]>(['Login', 'Signup']);

/** Access declared by the routes the invented modules link to, plus the shell's own two. */
const routeAccess: Record<string, RouteAccess | undefined> = {
    Home: undefined,
    Playground: undefined,
    PublicThing: undefined,
    MemberThing: 'auth',
    StaffThing: 'admin'
};

/*
 * Three invented domains, one per visibility class. `order` is deliberately out of sequence so the
 * sort is exercised rather than accidentally satisfied by declaration order.
 */
vi.mock('@/modules', () => ({
    enabledModules: [
        {
            name: 'staff-domain',
            routes: [],
            navigation: [{ name: 'StaffThing', label: 'navigation.label-staff', order: 90 }]
        },
        {
            name: 'public-domain',
            routes: [],
            navigation: [{ name: 'PublicThing', label: 'navigation.label-public', order: 30 }]
        },
        {
            name: 'member-domain',
            routes: [],
            navigation: [{ name: 'MemberThing', label: 'navigation.label-member', order: 60 }]
        }
    ]
}));

vi.mock('vue-i18n', async (importOriginal) => {
    const actual = await importOriginal<typeof import('vue-i18n')>();
    return {
        ...actual,
        useI18n: () => ({
            t: (key: string) => key,
            locale: ref('en')
        })
    };
});

vi.mock('vue-router', () => ({
    RouterLink: {
        template: '<a><slot /></a>'
    },
    useRoute: () => ({ fullPath: '/', params: {}, query: {} }),
    useRouter: () => ({
        push: vi.fn(),
        replace: vi.fn(),
        resolve: ({ name }: { name: string }) => ({ meta: { access: routeAccess[name] } }),
        hasRoute: (name: string) => registeredRoutes.value.includes(name)
    })
}));

vi.mock('@/infrastructure/stores/session.ts', () => ({
    useSessionStore: () => session
}));

/** Mounts the nav and returns the labels of the entries it rendered. */
const mountNav = () => {
    const wrapper = mount(AppNavigation, {
        global: {
            plugins: [createPinia(), vuetify],
            stubs: {
                // v-app-bar teleports into a v-app layout that does not exist here
                VAppBar: {
                    template:
                        '<header><slot name="prepend" /><slot /><slot name="append" /></header>'
                },
                VNavigationDrawer: { template: '<aside><slot /></aside>' }
            }
        }
    });
    return { wrapper, text: wrapper.text() };
};

describe('Navigation', () => {
    beforeEach(() => {
        session.isAuth.value = false;
        session.isAdmin.value = false;
        session.viewer.value = undefined;
        registeredRoutes.value = ['Login', 'Signup'];
    });

    it('renders properly', () => {
        expect(mountNav().wrapper).toBeTruthy();
    });

    it('shows a guest only the public entries', () => {
        const { text } = mountNav();

        expect(text).toContain('navigation.label-home');
        expect(text).toContain('navigation.label-public');
        expect(text).not.toContain('navigation.label-member');
        expect(text).not.toContain('navigation.label-staff');
    });

    it('adds the authenticated entries once logged in, but not the admin ones', () => {
        session.isAuth.value = true;

        const { text } = mountNav();

        expect(text).toContain('navigation.label-member');
        // The trap this guards: an admin-only page listed for every logged-in visitor.
        expect(text).not.toContain('navigation.label-staff');
    });

    it('shows the admin entries to an admin', () => {
        session.isAuth.value = true;
        session.isAdmin.value = true;

        const { text } = mountNav();

        expect(text).toContain('navigation.label-staff');
        expect(text).toContain('navigation.label-member');
    });

    it('orders module entries by `order`, not by module registration order', () => {
        session.isAuth.value = true;
        session.isAdmin.value = true;

        const { text } = mountNav();

        // staff-domain is registered first but ordered last.
        expect(text.indexOf('navigation.label-public')).toBeLessThan(
            text.indexOf('navigation.label-member')
        );
        expect(text.indexOf('navigation.label-member')).toBeLessThan(
            text.indexOf('navigation.label-staff')
        );
    });

    it('offers sign-in and sign-up when the account routes are registered', () => {
        const { text } = mountNav();

        expect(text).toContain('navigation.label-login');
        expect(text).toContain('navigation.label-signup');
    });

    it('offers neither when this build ships no sign-in route', () => {
        // A build with the account module deleted: the shell must not render a button that
        // navigates nowhere. Route names are strings, so only `hasRoute` can tell.
        registeredRoutes.value = [];

        const { text } = mountNav();

        expect(text).not.toContain('navigation.label-login');
        expect(text).not.toContain('navigation.label-signup');
    });

    it('renders the shell entries when no module contributes anything', () => {
        // The event-portal end state: every domain deleted, the shell still has a menu.
        const { text } = mountNav();

        expect(text).toContain('navigation.label-home');
        expect(text).toContain('navigation.label-about');
    });
});

