/**
 * The shared axios instance's configuration — `src/infrastructure/http/client.ts`.
 *
 * Both defaults are read from the environment at import time and both have a fallback, which is
 * exactly the shape that goes wrong silently: a missing `VITE_API_URL` that resolved to
 * `undefined` would make every relative call hit the dev server instead of the API, and a
 * missing timeout would make a hung request hang forever. So each arm is loaded on its own.
 */
import { afterEach, describe, expect, it, vi } from 'vitest';

/**
 * Imports the client fresh, so the module-scope env reads run again.
 *
 * @param env - Variables to stub before the import; anything omitted is unset.
 * @returns The freshly imported module.
 */
const loadClient = (env: Record<string, string | undefined>) => {
    vi.resetModules();
    for (const [key, value] of Object.entries(env))
        value === undefined ? vi.stubEnv(key, undefined) : vi.stubEnv(key, value);
    return import('@/infrastructure/http/client.ts');
};

afterEach(() => {
    vi.unstubAllEnvs();
});

describe('axios instance defaults', () => {
    it('takes the base URL and timeout from the environment', () => {
        return loadClient({ VITE_API_URL: 'http://api.test', VITE_AXIOS_TIMEOUT: '2500' }).then(
            ({ instance }) => {
                expect(instance.defaults.baseURL).toBe('http://api.test');
                expect(instance.defaults.timeout).toBe(2500);
            }
        );
    });

    it('falls back to same-origin relative calls and a ten second timeout', () => {
        return loadClient({ VITE_API_URL: undefined, VITE_AXIOS_TIMEOUT: undefined }).then(
            ({ instance }) => {
                // Empty string, not undefined: axios treats an undefined baseURL as "no prefix",
                // which is the same result by accident rather than by decision.
                expect(instance.defaults.baseURL).toBe('');
                expect(instance.defaults.timeout).toBe(10_000);
            }
        );
    });

    it('sends credentials, so the httpOnly refresh cookie travels with every call', () => {
        return loadClient({}).then(({ instance }) => {
            expect(instance.defaults.withCredentials).toBe(true);
        });
    });
});

tests/unit/infrastructure/stores/observa.source:
/**
 * Unit tests for the observability store.
 *
 * This file exists because the telemetry surface was the single largest untested area in the
 * repo — `src/infrastructure/observability.ts` alone carried 123 mutants with NO COVERAGE, which
 * is the standing statement that nothing here was ever exercised. See
 * `docs/tools/mutation-testing.md`.
 *
 * ── What is covered, and what deliberately is not ────────────────────────────────────────────
 * The **Umami half** and the **unified API** are covered: config reading, one-shot script
 * injection, the readiness guards, and every `track*` helper's event name and payload. All of it
 * is this repo's own logic and all of it is observable through `globalThis.umami` and the DOM.
 *
 * `initFaro` is NOT covered. It dynamically imports `@grafana/faro-web-sdk` and
 * `@grafana/faro-web-tracing` and hands them a real browser environment; a test would either
 * load two large SDKs into jsdom or mock them so thoroughly that it asserted only the shape of
 * the mock. What IS covered is every branch that Faro's absence controls — `identifyUser`,
 * `unidentifyUser` and `captureException` all have to be safe no-ops while it is off, and that
 * is the state a visitor with telemetry disabled is actually in.
 *
 * The Umami tracker is a global the real script attaches to `window`, so each test installs its
 * own and `afterEach` removes it — otherwise a test that never initialised analytics would still
 * see the previous one's spy.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useObservabilityStore } from '@/infrastructure/stores/observability.ts';
import { analyticsEvents } from '@/infrastructure/observability/events.ts';

/** Stands in for the object the Umami script attaches to `window` once it loads. */
const installUmamiTracker = () => {
    const tracker = { track: vi.fn(), identify: vi.fn() };
    globalThis.umami = tracker;
    return tracker;
};

/** Fire the `load` event on the injected tag, as the browser does once the script runs. */
const scriptLoads = () => {
    document.querySelector('script[data-website-id="site-1"]')?.dispatchEvent(new Event('load'));
};

/** A store with analytics switched on, which is the precondition for every `track` call. */
const readyStore = () => {
    vi.stubEnv('VITE_UMAMI_WEBSITE_ID', 'site-1');
    vi.stubEnv('VITE_UMAMI_SRC', 'https://umami.example.com/script.js');
    const store = useObservabilityStore();
    store.initUmami();
    return store;
};

describe('useObservabilityStore', () => {
    beforeEach(() => {
        setActivePinia(createPinia());
        vi.clearAllMocks();
        document.head.innerHTML = '';
    });

    afterEach(() => {
        vi.unstubAllEnvs();
        delete globalThis.umami;
    });

    describe('analyticsEvents', () => {
        it('carries both the shared catalogue and the frontend-only additions', () => {
            // The shared half is byte-identical with the backend and guarded by
            // `check:spec-identity`; the frontend-only half has no backend counterpart because
            // there is no "app started" on a server that is always started.
            expect(analyticsEvents.APP_STARTED).toBe('app_started');
            expect(analyticsEvents.USER_LOGGED_OUT).toBe('user_logged_out');
            expect(analyticsEvents.PRODUCT_VIEWED).toBeTruthy();
            expect(analyticsEvents.ORDER_CREATED).toBeTruthy();
        });
    });

    describe('initUmami', () => {
        it('stays off, and injects nothing, when no website id is configured', () => {
            vi.stubEnv('VITE_UMAMI_WEBSITE_ID', '');
            const store = useObservabilityStore();

            expect(store.initUmami()).toBe(false);
            expect(store.umamiReady).toBe(false);
            expect(document.querySelector('script[data-website-id]')).toBeNull();
        });

        it('treats a whitespace-only website id as unset', () => {
            // `.trim()` on the way in: a half-filled `.env` should disable analytics rather than
            // register a website whose id is a space.
            vi.stubEnv('VITE_UMAMI_WEBSITE_ID', '   ');
            expect(useObservabilityStore().initUmami()).toBe(false);
        });

        it('injects the deferred tracker script and reports itself ready', () => {
            const store = readyStore();

            const script = document.querySelector<HTMLScriptElement>(
                'script[data-website-id="site-1"]'
            );
            expect(script).not.toBeNull();
            expect(script?.src).toBe('https://umami.example.com/script.js');
            // Deferred, so the tracker never blocks first paint.
            expect(script?.defer).toBe(true);
            expect(store.umamiReady).toBe(true);
        });

        it('injects once, however many times it is called', () => {
            // The guard is against HMR and against a second caller, both of which would otherwise
            // leave two trackers on the page double-counting every pageview.
            const store = readyStore();
            store.initUmami();
            store.initUmami();

            expect(document.querySelectorAll('script[data-website-id="site-1"]')).toHaveLength(1);
        });
    });

    describe('track', () => {
        it('drops events until the tracker is ready', () => {
            const tracker = installUmamiTracker();
            // Deliberately no `initUmami()`: the script loads asynchronously, so the first
            // events of a session can arrive before it. Dropping them is the accepted trade.
            useObservabilityStore().track(analyticsEvents.APP_STARTED);

            expect(tracker.track).not.toHaveBeenCalled();
        });

        it('forwards the event and its properties once ready', () => {
            const tracker = installUmamiTracker();
            readyStore().track(analyticsEvents.APP_READY, { boot_ms: 12 });

            expect(tracker.track).toHaveBeenCalledWith('app_ready', { boot_ms: 12 });
        });

        it('does not throw when the script has not attached its global yet', () => {
            // `umamiReady` says "we injected the tag", not "the script finished loading". The
            // buffer is what keeps that window from throwing into a caller's promise.
            const store = readyStore();
            delete globalThis.umami;

            expect(() => store.track(analyticsEvents.APP_READY)).not.toThrow();
        });
    });

    /**
     * The window between injecting the tag and the tracker existing is one network round-trip
     * long, and `main.ts` emits `app_started` inside it — every session, without exception. While
     * those events were dropped, the two boot events in the catalogue could not appear in a
     * dashboard at all: not rare, not lossy, simply never recorded.
     *
     * These cases pin the buffer to that scenario rather than to its implementation — what is
     * asserted is that an event tracked before the script lands arrives after it does.
     */
    describe('events tracked before the tracker arrives', () => {
        it('are delivered once the script loads, not dropped', () => {
            const store = readyStore();

            // The real boot order: the tag is in the document, the tracker is not there yet.
            store.track(analyticsEvents.APP_STARTED);

            const tracker = installUmamiTracker();
            scriptLoads();

            expect(tracker.track).toHaveBeenCalledWith('app_started', undefined);
        });

        it('keep their order and their properties', () => {
            const store = readyStore();

            store.track(analyticsEvents.APP_STARTED);
            store.track(analyticsEvents.APP_READY, { boot_ms: 12 });

            const tracker = installUmamiTracker();
            scriptLoads();

            expect(tracker.track.mock.calls).toEqual([
                ['app_started', undefined],
                ['app_ready', { boot_ms: 12 }]
            ]);
        });

        it('are sent once, however many times the buffer is flushed', () => {
            const store = readyStore();
            store.track(analyticsEvents.APP_STARTED);

            const tracker = installUmamiTracker();
            scriptLoads();
            scriptLoads();

            expect(tracker.track).toHaveBeenCalledTimes(1);
        });

        it('go straight through once the tracker exists, without queueing', () => {
            const tracker = installUmamiTracker();
            const store = readyStore();

            store.track(analyticsEvents.APP_READY);

            // Already delivered before any load event: nothing was buffered.
            expect(tracker.track).toHaveBeenCalledTimes(1);
            scriptLoads();
            expect(tracker.track).toHaveBeenCalledTimes(1);
        });

        it('stop accumulating when the script never arrives', () => {
            // An ad blocker, or a Umami that is down. The buffer must not grow for the lifetime
            // of the tab; the newest events are the ones worth keeping.
            const store = readyStore();

            for (let index = 0; index < 60; index += 1) {
                store.track(analyticsEvents.PRODUCT_VIEWED, { index });
            }

            const tracker = installUmamiTracker();
            scriptLoads();

            expect(tracker.track).toHaveBeenCalledTimes(50);
            // The oldest ten were evicted, so the first survivor is number 10.
            expect(tracker.track.mock.calls[0]).toEqual([
                analyticsEvents.PRODUCT_VIEWED,
                { index: 10 }
            ]);
        });

        it('are dropped, not buffered, while analytics is disabled', () => {
            // No script is coming, so a buffer would only ever grow.
            vi.stubEnv('VITE_UMAMI_WEBSITE_ID', '');
            const store = useObservabilityStore();
            store.track(analyticsEvents.APP_STARTED);

            const tracker = installUmamiTracker();
            scriptLoads();

            expect(tracker.track).not.toHaveBeenCalled();
        });
    });

    /**
     * The convenience helpers exist so that call sites cannot invent their own property names —
     * a dashboard groups by `product_id`, and one caller sending `productId` is a silent hole in
     * the funnel. So the payload keys are the thing worth pinning, not just the event name.
     */
    describe('convenience helpers', () => {
        it('trackProductView sends the product id and name', () => {
            const tracker = installUmamiTracker();
            readyStore().trackProductView('p1', 'Gadget');

            expect(tracker.track).toHaveBeenCalledWith(analyticsEvents.PRODUCT_VIEWED, {
                product_id: 'p1',
                product_name: 'Gadget'
            });
        });

        it('trackItemAddedToCart sends the product id and quantity', () => {
            const tracker = installUmamiTracker();
            readyStore().trackItemAddedToCart('p1', 3);

            expect(tracker.track).toHaveBeenCalledWith(analyticsEvents.CART_ITEM_ADDED, {
                product_id: 'p1',
                quantity: 3
            });
        });

        it('trackOrderPlaced sends the order id, total and line count', () => {
            const tracker = installUmamiTracker();
            readyStore().trackOrderPlaced('o1', 19.98, 2);

            expect(tracker.track).toHaveBeenCalledWith(analyticsEvents.ORDER_CREATED, {
                order_id: 'o1',
                total_amount: 19.98,
                item_count: 2
            });
        });

        it('trackProductSearched sends the raw query', () => {
            const tracker = installUmamiTracker();
            readyStore().trackProductSearched('gad');

            expect(tracker.track).toHaveBeenCalledWith(analyticsEvents.PRODUCTS_SEARCHED, {
                query: 'gad'
            });
        });
    });

    /**
     * Identity and error reporting with Faro OFF.
     *
     * This is the state of every visitor in a build with no `VITE_FARO_URL`, and of every visitor
     * before `initFaro` resolves. None of these may throw: `captureException` in particular is
     * called from the router's `onError`, so a throw here would replace a page error with a
     * crash inside the error handler.
     */
    describe('with Faro disabled', () => {
        it('identifyUser still reaches Umami', () => {
            const tracker = installUmamiTracker();
            useObservabilityStore().identifyUser('u1', 'ada@example.com');

            expect(tracker.identify).toHaveBeenCalledWith({
                id: 'u1',
                email: 'ada@example.com'
            });
        });

        it('identifyUser tolerates a tracker without identify (pre-2.11 Umami)', () => {
            globalThis.umami = { track: vi.fn() };

            expect(() => useObservabilityStore().identifyUser('u1')).not.toThrow();
        });

        it('identifyUser tolerates no tracker at all', () => {
            expect(() => useObservabilityStore().identifyUser('u1')).not.toThrow();
        });

        it('unidentifyUser is a no-op', () => {
            expect(() => useObservabilityStore().unidentifyUser()).not.toThrow();
        });

        it('captureException is a no-op, whatever it is handed', () => {
            const store = useObservabilityStore();

            expect(() => store.captureException(new Error('boom'))).not.toThrow();
            // Non-Error values reach it too — a rejected promise can carry anything.
            expect(() => store.captureException('a string')).not.toThrow();
            expect(() => store.captureException(undefined)).not.toThrow();
            expect(() =>
                store.captureException(new Error('boom'), { data: { orderId: 'o1' } })
            ).not.toThrow();
        });

        it('reports Faro as not ready', () => {
            expect(useObservabilityStore().faroReady).toBe(false);
        });
    });
});

tests/unit/infrastructure/i18n/i18n.spec.source:
import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { createI18n } from 'vue-i18n';
import type { TranslationDictionaries } from '@/infrastructure/i18n';
import {
    API_NAMESPACE,
    apiText,
    getCurrentLocale,
    getDefaultLocale,
    loadedLanguages,
    _changeLanguage,
    _ensureFallbackLoaded,
    _loadLocale,
    _updateLocale,
    i18n,
    registerLocaleContributors
} from '@/infrastructure/i18n';
import { routerLinkI18n } from '@/infrastructure/i18n/routerLink.ts';
import enMessages from '@/locales/en.json';
import itMessages from '@/locales/it.json';

/**
 * The locale machinery itself, against a REAL vue-i18n instance.
 *
 * This layer had no test at all. The one locale spec that existed —
 * `tests/unit/app/guards/localeChoice.spec.ts` — mocks `@/infrastructure/i18n` wholesale, so it
 * asserts that `changeLanguage` *was called with* `'it'` and never that anything became Italian.
 * That is the right way to test a router guard, and it left everything underneath unverified.
 *
 * The `_`-prefixed functions take the instance to act on, which is exactly so a test can use a
 * throwaway one instead of mutating the app-wide singleton. `supportedLanguages` and
 * `loadedLanguages` are module state shared with that singleton, so anything touching them is
 * restored afterwards.
 */

const freshInstance = () => createI18n({ legacy: false, locale: 'en', fallbackLocale: 'en' });

/** Restores `loadedLanguages` to whatever it held before a test pushed to it. */
const withLoadedLanguagesRestored = () => {
    const snapshot = [...loadedLanguages];
    return () => loadedLanguages.splice(0, Number.POSITIVE_INFINITY, ...snapshot);
};

describe('supportedLanguages', () => {
    afterEach(() => {
        vi.unstubAllEnvs();
        vi.resetModules();
    });

    it('comes from VITE_APP_SUPPORTED_LOCALES', () => {
        vi.stubEnv('VITE_APP_SUPPORTED_LOCALES', 'en,it,es');
        vi.resetModules();
        return import('@/infrastructure/i18n').then((reloaded) => {
            expect(reloaded.supportedLanguages).toContain('en');
            expect(reloaded.supportedLanguages).toContain('it');
            expect(reloaded.supportedLanguages).toContain('es');
        });
    });

    /**
     * The whole point of the supported/loaded split: a locale can be offered before its
     * dictionary is anywhere near the bundle. `es` is declared in `.env` and has no
     * `src/locales/es.json`, which is the case the runtime fetch exists for.
     */
    it('may list a locale with no local dictionary', () => {
        vi.stubEnv('VITE_APP_SUPPORTED_LOCALES', 'en,it,es');
        vi.resetModules();
        return import('@/infrastructure/i18n').then((reloaded) => {
            expect(reloaded.supportedLanguages).toContain('es');
        });
    });
});

describe('_loadLocale', () => {
    let restore: () => void;

    beforeEach(() => {
        restore = withLoadedLanguagesRestored();
    });
    afterEach(() => restore());

    it('imports and activates a supported locale that is not loaded yet', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.locale.value).toBe('it');
            expect(loadedLanguages).toContain('it');
            expect(instance.global.t('navigation.error-already-logged')).toBe(
                itMessages.navigation['error-already-logged']
            );
        });
    });

    it('short-circuits when the locale is already loaded', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0, Number.POSITIVE_INFINITY, 'it');
        // Registered by hand rather than imported: if the short circuit is broken and the real
        // file is fetched, this sentinel is overwritten and the assertion fails.
        instance.global.setLocaleMessage('it', { sentinel: 'not-from-the-file' });
        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.t('sentinel')).toBe('not-from-the-file');
            expect(instance.global.locale.value).toBe('it');
        });
    });

    it('falls back to the default locale for an unsupported one', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        return _loadLocale(instance, 'kl').then(() => {
            expect(instance.global.locale.value).toBe(getDefaultLocale());
        });
    });

    /**
     * `es` is supported but has no file, so the dynamic import rejects. The documented contract
     * is that this degrades to the default locale rather than rejecting: callers have no
     * `.catch`, and a failed dictionary must never strand a navigation.
     */
    it('falls back to the default locale when the import fails', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        return expect(_loadLocale(instance, 'es'))
            .resolves.not.toThrow()
            .then(() => {
                expect(instance.global.locale.value).toBe(getDefaultLocale());
            });
    });
});

describe('_updateLocale', () => {
    let restore: () => void;

    beforeEach(() => {
        restore = withLoadedLanguagesRestored();
    });
    afterEach(() => restore());

    it('registers a dictionary fetched from somewhere other than the bundle', () => {
        const instance = freshInstance();
        return _updateLocale(instance, 'es', { greeting: 'Hola' }).then(() => {
            instance.global.locale.value = 'es';
            expect(instance.global.t('greeting')).toBe('Hola');
            expect(loadedLanguages).toContain('es');
        });
    });

    it('overwrites an existing dictionary without duplicating the loaded entry', () => {
        const instance = freshInstance();
        return _updateLocale(instance, 'es', { greeting: 'Hola' })
            .then(() => {
                return _updateLocale(instance, 'es', { greeting: 'Buenas' });
            })
            .then(() => {
                instance.global.locale.value = 'es';
                expect(instance.global.t('greeting')).toBe('Buenas');
                expect(loadedLanguages.filter((locale) => locale === 'es')).toHaveLength(1);
            });
    });
});

describe('_changeLanguage', () => {
    let restore: () => void;

    beforeEach(() => {
        restore = withLoadedLanguagesRestored();
    });
    afterEach(() => restore());

    /**
     * `<html lang>` is not decoration: it tells screen readers which pronunciation rules to use
     * and browsers whether to offer a translation. Nothing else in the app sets it.
     */
    it('keeps <html lang> in sync', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0, Number.POSITIVE_INFINITY, 'it');
        return _changeLanguage(instance, 'it').then(() => {
            expect(document.documentElement.getAttribute('lang')).toBe('it');
        });
    });

    /**
     * `fallbackLocale` is inert unless the fallback's messages are registered. Without loading
     * it, landing directly on a locale this app has no dictionary for leaves EVERY UI key
     * rendering as its own raw identifier — there is nothing to fall back to.
     */
    it('loads the fallback dictionary too, so per-key fallback actually works', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);

        // A locale with no local dictionary — the API-only case.
        return _updateLocale(instance, 'es', { api: { greeting: 'Hola' } })
            .then(() => _changeLanguage(instance, 'es'))
            .then(() => {
                expect(instance.global.locale.value).toBe('es');
                expect(loadedLanguages).toContain('en');
                // Falls through to the English copy rather than echoing the key back.
                expect(instance.global.t('navigation.error-already-logged')).toBe(
                    enMessages.navigation['error-already-logged']
                );
            });
    });

    it('does not try to load the fallback when it is the locale being activated', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0, Number.POSITIVE_INFINITY, 'en');
        return expect(_ensureFallbackLoaded(instance, 'en')).resolves.toBeUndefined();
    });

    it('loads the dictionary first when the locale has never been loaded', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        return _changeLanguage(instance, 'it').then(() => {
            expect(instance.global.locale.value).toBe('it');
            expect(instance.global.t('navigation.error-already-logged')).toBe(
                itMessages.navigation['error-already-logged']
            );
        });
    });
});

describe('getDefaultLocale', () => {
    afterEach(() => {
        vi.unstubAllGlobals();
        vi.unstubAllEnvs();
        vi.resetModules();
    });

    it('uses the browser language when it is supported', () => {
        vi.stubGlobal('navigator', { language: 'it-IT' });
        expect(getDefaultLocale()).toBe('it');
    });

    it('falls back when the browser language is not supported', () => {
        vi.stubGlobal('navigator', { language: 'kl-GL' });
        expect(getDefaultLocale()).toBe('en');
    });

    /**
     * The check is against SUPPORTED, not loaded, languages. On a first visit nothing is loaded
     * yet, so a `loadedLanguages` check would never match and browser detection would be dead
     * code that always returned the fallback.
     */
    it('matches a browser language whose dictionary is not loaded yet', () => {
        vi.stubEnv('VITE_APP_SUPPORTED_LOCALES', 'en,it,es');
        vi.resetModules();
        return import('@/infrastructure/i18n').then((reloaded) => {
            vi.stubGlobal('navigator', { language: 'es-ES' });
            expect(reloaded.getDefaultLocale()).toBe('es');
        });
    });
});

describe('routerLinkI18n', () => {
    beforeEach(() => {
        i18n.global.locale.value = 'en';
    });

    it('prefixes a plain path string', () => {
        expect(routerLinkI18n('/products')).toBe('/en/products');
    });

    it('normalises a relative path', () => {
        expect(routerLinkI18n('products')).toBe('/en/products');
    });

    it('leaves an already-prefixed path alone', () => {
        expect(routerLinkI18n('/it/products')).toBe('/it/products');
    });

    it('prefixes the path of a path-based location object', () => {
        expect(routerLinkI18n({ path: '/products', query: { page: '2' } })).toEqual({
            path: '/en/products',
            query: { page: '2' }
        });
    });

    it('injects the locale into params for a named location', () => {
        expect(routerLinkI18n({ name: 'Products' })).toEqual({
            name: 'Products',
            params: { locale: 'en' }
        });
    });

    it('lets an explicit params.locale win', () => {
        expect(routerLinkI18n({ name: 'Products', params: { locale: 'it' } })).toEqual({
            name: 'Products',
            params: { locale: 'it' }
        });
    });

    /**
     * The documented trap: vue-router IGNORES `params` whenever `path` is present. So a
     * `path`-based location must have the locale put into the path itself — injecting
     * `params.locale` would be silently dropped, and a bare `/products` would then match
     * `/:locale` with `locale = "products"`.
     */
    it('does not try to use params for a path-based location', () => {
        const result = routerLinkI18n({ path: '/products' }) as { path: string; params?: unknown };

        expect(result.path).toBe('/en/products');
        expect(result.params).toBeUndefined();
    });

    it('follows the active locale', () => {
        // Synchronous: nothing here awaited anything, the `async` was vestigial.
        i18n.global.locale.value = 'it';
        expect(routerLinkI18n('/products')).toBe('/it/products');
        expect(getCurrentLocale()).toBe('it');
    });
});

describe('apiText and the reserved api.* namespace', () => {
    let restore: () => void;

    beforeEach(() => {
        restore = withLoadedLanguagesRestored();
        i18n.global.locale.value = 'en';
    });
    afterEach(() => {
        restore();
        // Re-register the bundled dictionary, dropping anything merged under `api.*`.
        // `_updateLocale` clones, so this cannot write back into the imported JSON — which is
        // exactly the property the clone exists for.
        void _updateLocale(i18n, 'en', enMessages as TranslationDictionaries);
    });

    it('uses this app’s own copy when the API dictionary is absent', () => {
        return _loadLocale(i18n, 'en').then(() => {
            expect(apiText('generic.error-unknown', 'api-errors.unknown')).toBe(
                enMessages['api-errors'].unknown
            );
        });
    });

    it('prefers the API’s own wording once its dictionary is registered', () => {
        return _loadLocale(i18n, 'en').then(() => {
            i18n.global.mergeLocaleMessage('en', {
                [API_NAMESPACE]: { generic: { ['error-unknown']: 'Server says so' } }
            });
            expect(apiText('generic.error-unknown', 'api-errors.unknown')).toBe('Server says so');
        });
    });

    it('never returns a raw key', () => {
        return _loadLocale(i18n, 'en').then(() => {
            expect(apiText('nothing.at.all', 'api-errors.unknown')).toBe(
                enMessages['api-errors'].unknown
            );
        });
    });
});

describe('locale files', () => {
    /**
     * Every leaf key, dot-joined and sorted.
     */
    const flattenKeys = (dictionary: Record<string, unknown>, prefix = ''): string[] =>
        Object.entries(dictionary)
            .flatMap(([key, value]) =>
                value !== null && typeof value === 'object'
                    ? flattenKeys(value as Record<string, unknown>, `${prefix}${key}.`)
                    : [`${prefix}${key}`]
            )
            .toSorted();

    it('en.json and it.json declare exactly the same keys', () => {
        expect(flattenKeys(itMessages as Record<string, unknown>)).toEqual(
            flattenKeys(enMessages as Record<string, unknown>)
        );
    });

    it('it.json is actually translated, not a copy of en.json', () => {
        expect(itMessages.navigation['error-already-logged']).not.toBe(
            enMessages.navigation['error-already-logged']
        );
    });

    /**
     * `api` belongs to the backend and arrives at runtime. A hand-authored key under it would be
     * silently overwritten by the fetched dictionary — or worse, silently shadow it.
     */
    it.each([
        ['en', enMessages],
        ['it', itMessages]
    ])('%s.json declares no key under the reserved api namespace', (_locale, messages) => {
        expect(Object.keys(messages)).not.toContain(API_NAMESPACE);
    });
});

/**
 * Module-load-time branches.
 *
 * `supportedLanguages` and the empty-list guard are evaluated once, when the module is first
 * imported, from `import.meta.env`. They cannot be reached by calling anything — only by
 * re-importing the module under different env, which is what `resetModules` + `stubEnv` do here.
 *
 * Worth the machinery because both branches are failure-mode code: one is how the app discovers
 * its locales when no env list is configured, the other is what keeps it from booting with an
 * empty language list. Neither had ever been executed by a test.
 */
describe('module-load configuration', () => {
    beforeEach(() => {
        vi.resetModules();
    });

    afterEach(() => {
        vi.unstubAllEnvs();
        vi.resetModules();
    });

    it('derives the locale list from src/locales when no env list is set', () => {
        vi.stubEnv('VITE_APP_SUPPORTED_LOCALES', '');
        return import('@/infrastructure/i18n').then((reloaded) => {
            // The glob sees the real directory: en.json and it.json ship, es.json deliberately does
            // not (it is the API-only locale).
            expect(reloaded.supportedLanguages).toContain('en');
            expect(reloaded.supportedLanguages).toContain('it');
            expect(reloaded.supportedLanguages).not.toContain('es');
        });
    });

    it.each([
        ['an empty value', ''],
        ['only separators', ',,'],
        ['only whitespace', '  ,  ']
    ])('treats %s as "not configured" and discovers from the folder instead', (_l, value) => {
        vi.stubEnv('VITE_APP_SUPPORTED_LOCALES', value);
        return import('@/infrastructure/i18n').then((reloaded) => {
            expect(reloaded.supportedLanguages).toEqual(['en', 'it']);
        });
    });

    /**
     * Both slips are silent, and neither looks like a locale bug when it bites — see the
     * normalisation note on `declaredLocales`. The empty-entry case is the nastier one: `''`
     * matches the empty first segment of `/`, so `routerLinkI18n('/')` would stop prefixing the
     * locale and the root route would quietly lose its language.
     */
    it.each([
        ['spaces after the commas', 'en, it, es'],
        ['a stray comma', 'en,,it,es'],
        ['a trailing comma', 'en,it,es,']
    ])('normalises %s', (_label, value) => {
        vi.stubEnv('VITE_APP_SUPPORTED_LOCALES', value);
        return import('@/infrastructure/i18n').then((reloaded) => {
            expect(reloaded.supportedLanguages).not.toContain('');
            expect(reloaded.supportedLanguages.every((l) => l === l.trim())).toBe(true);
            expect(reloaded.supportedLanguages).toEqual(expect.arrayContaining(['en', 'it', 'es']));
        });
    });

    it('keeps a locale the bundle has no dictionary for, so the API can serve it', () => {
        vi.stubEnv('VITE_APP_SUPPORTED_LOCALES', 'en,it,es');
        return import('@/infrastructure/i18n').then((reloaded) => {
            expect(reloaded.supportedLanguages).toContain('es');
        });
    });
});

/**
 * The one custom message modifier the dictionaries actually use — `it.json`'s
 * `products-list-page.modified-products-list` is `@.customSnakeCase:{'generic.product'}`.
 */
describe('the customSnakeCase modifier', () => {
    it('joins a linked message’s words with underscores', () => {
        return _updateLocale(i18n, 'en', {
            ...(enMessages as TranslationDictionaries),
            ['modifier-probe']: "@.customSnakeCase:{'modifier-source'}",
            ['modifier-source']: 'two words'
        }).then(() => {
            i18n.global.locale.value = 'en';
            expect(i18n.global.t('modifier-probe')).toBe('two_words');
            return _updateLocale(i18n, 'en', enMessages as TranslationDictionaries);
        });
    });
});

/**
 * Dictionary merging — locales merge at boot, not at build.
 *
 * Each module ships its own `locales/{en,it}.json` and registers a loader for it; `_loadLocale`
 * pulls the shared file plus every registered loader and merges them into one locale. The merge
 * has to be DEEP, because several modules each contribute a slice of the same `navigation`
 * namespace — a shallow merge would leave the last writer's slice and silently drop the rest,
 * which looks exactly like a missing translation and not at all like a bug in the loader.
 *
 * Synthetic contributors rather than the real modules: this is core, and which domains exist is
 * not its business. `cross-cutting/schemas-i18n.spec.ts` is where the real dictionaries are swept.
 */
describe('registerLocaleContributors', () => {
    let restore: () => void;

    beforeEach(() => {
        restore = withLoadedLanguagesRestored();
    });

    afterEach(() => {
        restore();
        // Module state shared with the app-wide singleton — leave it as it was found.
        registerLocaleContributors({});
    });

    it('merges a contributed dictionary on top of the shared one', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        registerLocaleContributors({
            it: [() => Promise.resolve({ madeUpPage: { title: 'Titolo' } })]
        });

        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.t('madeUpPage.title')).toBe('Titolo');
            // and the shared dictionary is still there
            expect(instance.global.t('navigation.error-already-logged')).toBe(
                itMessages.navigation['error-already-logged']
            );
        });
    });

    it('deep-merges two contributors into one shared namespace', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        registerLocaleContributors({
            it: [
                () => Promise.resolve({ navigation: { labelAlpha: 'Alfa' } }),
                () => Promise.resolve({ navigation: { labelBeta: 'Beta' } })
            ]
        });

        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.t('navigation.labelAlpha')).toBe('Alfa');
            expect(instance.global.t('navigation.labelBeta')).toBe('Beta');
            // the shared file's own entries under the same namespace survive both
            expect(instance.global.t('navigation.error-already-logged')).toBe(
                itMessages.navigation['error-already-logged']
            );
        });
    });

    it('ignores contributors registered for a different locale', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        registerLocaleContributors({
            en: [() => Promise.resolve({ madeUpPage: { title: 'Title' } })]
        });

        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.te('madeUpPage.title', 'it')).toBe(false);
        });
    });

    it('replaces the previous registration instead of accumulating', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        registerLocaleContributors({
            it: [() => Promise.resolve({ madeUpPage: { title: 'First' } })]
        });
        registerLocaleContributors({
            it: [() => Promise.resolve({ madeUpPage: { title: 'Second' } })]
        });

        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.t('madeUpPage.title')).toBe('Second');
        });
    });

    /**
     * The regression this whole block exists for.
     *
     * The running app does NOT reach a first locale through `_loadLocale`. `localeChoice`, the
     * router guard, builds the dictionary itself (shared file + the API's `api.*` namespace) and
     * installs it with `updateLocale`. When the module merge lived in `_loadLocale` only, every
     * unit test passed and the browser rendered `products-list-page.title` as its own key on the
     * very first navigation — 24 e2e failures, all of them module-owned copy.
     *
     * So the merge belongs at the install point. This asserts the guard's path specifically.
     */
    it('merges contributors when a locale is installed via _updateLocale, not just _loadLocale', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        registerLocaleContributors({
            it: [() => Promise.resolve({ madeUpPage: { title: 'Titolo' } })]
        });

        // Exactly what `localeChoice` does: hand over an already-assembled dictionary.
        return _updateLocale(instance, 'it', {
            navigation: { ['error-already-logged']: 'Sei già loggato' },
            api: {}
        }).then(() => {
            instance.global.locale.value = 'it';
            expect(instance.global.t('madeUpPage.title')).toBe('Titolo');
            // and the caller's own dictionary survived the merge
            expect(instance.global.t('navigation.error-already-logged')).toBe('Sei già loggato');
        });
    });

    it('loads the shared dictionary alone when no module contributes', () => {
        const instance = freshInstance();
        loadedLanguages.splice(0);
        registerLocaleContributors({});

        return _loadLocale(instance, 'it').then(() => {
            expect(instance.global.t('navigation.error-already-logged')).toBe(
                itMessages.navigation['error-already-logged']
            );
        });
    });
});

