/**
 * Unit tests for the account store's `signup`.
 *
 * Same shape as the products/users store specs: `@api` is NOT mocked, because the multipart
 * encoding is exactly what is under test and it lives in the generated client. The transport
 * (`orvalMutator`) is mocked instead, so every assertion is about the request that actually goes
 * out — JSON body vs. `FormData`, and which URL it lands on.
 *
 * `openapi.yaml` declares `SignupRequest.imageUpload` and the generator emits
 * `signupWithMultipart` for it, so the branch that picks between the two clients is the thing
 * worth pinning: a store that only ever called the JSON one would still pass a shape test.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

import { useAccountStore } from '@/modules/account/store.ts';
import { orvalMutator } from '@/infrastructure/http';

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn(() =>
        Promise.resolve({ data: { id: 'u1', username: 'ada', email: 'ada@example.com' } })
    )
}));

/** The axios config handed to orvalMutator on its most recent call. */
const lastRequest = () => {
    const call = vi.mocked(orvalMutator).mock.calls.at(-1);
    if (!call) throw new Error('orvalMutator was never called');
    return call[0] as { url: string; method: string; data: unknown };
};

/** As above, asserting the body was multipart-encoded. */
const lastFormData = () => {
    const { data } = lastRequest();
    if (!(data instanceof FormData)) throw new Error('last request body was not FormData');
    return data;
};

const IMAGE = () => new File(['x'], 'avatar.png', { type: 'image/png' });

/** A fully-specified account, for the cases that are not about the defaults. */
const CREDENTIALS = {
    email: 'ada@example.com',
    password: 'hunter2hunter2',
    username: 'ada',
    passwordConfirm: 'hunter2hunter2'
};

describe('useAccountStore.signup', () => {
    beforeEach(() => {
        setActivePinia(createPinia());
        vi.clearAllMocks();
    });

    it('posts JSON when no image is attached', () =>
        useAccountStore()
            .signup({ email: 'ada@example.com', password: 'hunter2hunter2' })
            .then(() => {
                const request = lastRequest();
                expect(request).toMatchObject({ url: '/account/signup', method: 'POST' });
                expect(request.data).not.toBeInstanceOf(FormData);
                expect(request.data).toMatchObject({ email: 'ada@example.com' });
            }));

    it('posts multipart to the same endpoint when an image is attached', () =>
        useAccountStore()
            .signup({ ...CREDENTIALS, imageUpload: IMAGE() })
            .then(() => {
                expect(lastRequest()).toMatchObject({ url: '/account/signup', method: 'POST' });
                expect(lastFormData().get('imageUpload')).toBeInstanceOf(File);
            }));

    it('carries every scalar field into the multipart body, not just the file', () =>
        useAccountStore()
            .signup({ ...CREDENTIALS, imageUpload: IMAGE() })
            .then(() => {
                const formData = lastFormData();
                expect(formData.get('email')).toBe('ada@example.com');
                expect(formData.get('username')).toBe('ada');
                expect(formData.get('password')).toBe('hunter2hunter2');
                expect(formData.get('passwordConfirm')).toBe('hunter2hunter2');
            }));

    /**
     * The username default is `email`, and it survives the switch to multipart — a JSON-only
     * default that the other branch quietly dropped would be invisible until a signup with an
     * avatar produced an account named `undefined`.
     */
    it('applies the same username default on both branches', () => {
        const store = useAccountStore();

        return store
            .signup({ email: 'ada@example.com', password: 'hunter2hunter2' })
            .then(() => {
                expect(lastRequest().data).toMatchObject({ username: 'ada@example.com' });
                return store.signup({
                    email: 'ada@example.com',
                    password: 'hunter2hunter2',
                    imageUpload: IMAGE()
                });
            })
            .then(() => {
                expect(lastFormData().get('username')).toBe('ada@example.com');
            });
    });

    /**
     * `orvalMutator`'s second argument is the whole reason it takes one — `Signup.vue` passes
     * `onUploadProgress` through it to drive the progress bar.
     */
    it('forwards the upload progress callback to the transport', () => {
        const onUploadProgress = vi.fn();

        return useAccountStore()
            .signup({ ...CREDENTIALS, imageUpload: IMAGE() }, { onUploadProgress })
            .then(() => {
                expect(orvalMutator).toHaveBeenCalledWith(
                    expect.anything(),
                    expect.objectContaining({ onUploadProgress })
                );
            });
    });

    it('keeps the store id stable', () => {
        // Pinia keys the store, devtools and any persistence plugin by this string, and every
        // other test here reaches the store through `useAccountStore()` so none would notice.
        expect(useAccountStore().$id).toBe('account');
    });

    it('never parks the uploaded File in store state', () => {
        const store = useAccountStore();

        return store.signup({ ...CREDENTIALS, imageUpload: IMAGE() }).then(() => {
            expect(JSON.stringify(store.profile ?? {})).not.toContain('imageUpload');
        });
    });
});

/**
 * The address book.
 *
 * All four endpoints answer with the WHOLE book rather than with the row that changed, because
 * the invariant worth rendering after any write — exactly one default — is a property of the
 * list. So the thing to pin for each is the same: the right request goes out, and the local list
 * is replaced by the answer rather than patched locally.
 *
 * `removeAddress` is the one where that matters most: deleting the default promotes the oldest
 * survivor server-side, so a store that removed the row locally would show a book with no
 * default at all until the next reload.
 */
/** Makes the transport answer every address endpoint with this book. */
const respondWithBook = (addresses: unknown[]) =>
    vi.mocked(orvalMutator).mockResolvedValue({ data: { addresses } } as never);

describe('useAccountStore addresses', () => {
    const HOME = {
        id: 'a1',
        label: 'home',
        fullName: 'Ada Lovelace',
        street: '1 Main St',
        city: 'Springfield',
        zip: '11111',
        country: 'US',
        default: true
    };
    const WORK = {
        id: 'a2',
        label: 'office',
        fullName: 'Ada Lovelace',
        street: '2 Side St',
        city: 'Shelbyville',
        zip: '22222',
        country: 'US',
        default: false
    };

    beforeEach(() => {
        setActivePinia(createPinia());
        vi.clearAllMocks();
    });

    it('starts empty, before anything is fetched', () => {
        expect(useAccountStore().addresses).toEqual([]);
    });

    it('fetches the book and stores it', () => {
        respondWithBook([HOME, WORK]);
        const store = useAccountStore();

        return store.fetchAddresses().then((result) => {
            expect(lastRequest()).toMatchObject({ url: '/account/addresses', method: 'GET' });
            expect(store.addresses).toEqual([HOME, WORK]);
            expect(result).toEqual([HOME, WORK]);
        });
    });

    it('posts a new entry and replaces the book with the answer', () => {
        respondWithBook([HOME, WORK]);
        const store = useAccountStore();

        const { id: _id, default: _default, ...input } = WORK;

        return store.addAddress(input).then(() => {
            expect(lastRequest()).toMatchObject({ url: '/account/addresses', method: 'POST' });
            expect(store.addresses).toEqual([HOME, WORK]);
        });
    });

    it('puts a change to one entry, addressed by id', () => {
        respondWithBook([{ ...HOME, city: 'Ogdenville' }]);
        const store = useAccountStore();

        return store.updateAddress('a1', { city: 'Ogdenville' }).then(() => {
            expect(lastRequest()).toMatchObject({
                url: '/account/addresses/a1',
                method: 'PUT'
            });
            expect(store.addresses).toEqual([{ ...HOME, city: 'Ogdenville' }]);
        });
    });

    it('deletes an entry and takes the promoted default from the answer', () => {
        const store = useAccountStore();
        respondWithBook([HOME, WORK]);

        return store
            .fetchAddresses()
            .then(() => {
                // The server promotes WORK on deleting the default; the client must not guess it.
                respondWithBook([{ ...WORK, default: true }]);
                return store.removeAddress('a1');
            })
            .then(() => {
                expect(lastRequest()).toMatchObject({
                    url: '/account/addresses/a1',
                    method: 'DELETE'
                });
                expect(store.addresses).toEqual([{ ...WORK, default: true }]);
            });
    });

    it('reads a book-less payload as an empty book rather than as undefined', () => {
        // The `?? []` in `readAddressesResponse`. Every consumer does `addresses.map(...)`, so
        // an undefined here is a render crash rather than an empty state.
        vi.mocked(orvalMutator).mockResolvedValue({ data: {} } as never);
        const store = useAccountStore();

        return store.fetchAddresses().then((result) => {
            expect(result).toEqual([]);
            expect(store.addresses).toEqual([]);
        });
    });
});

src/modules/orders/tests/schemas-i18n.sp.source:
/**
 * Orders' validation messages follow the active locale.
 *
 * The MECHANISM — that a thunked Zod message re-resolves at parse time — is proven once, with an
 * invented schema, in `tests/cross-cutting/schemas-i18n.spec.ts`. What is proven here is that THIS
 * module's schemas and THIS module's dictionaries actually agree: every key the schemas reach for
 * exists in both languages, and the Italian copy is not the English copy.
 *
 * That is a fact about this domain, so it lives with it — deleting the folder deletes the coverage
 * rather than breaking a spec that belongs to nobody. See `docs/theory/modules.md`.
 *
 * Against the real vue-i18n instance, with the modules wired in as `src/main.ts` does: a mocked
 * `t` would assert only that a key was looked up, which stays true when the message is frozen in
 * the wrong language.
 */
import { describe, it, expect, beforeAll, afterEach } from 'vitest';
import { nextTick } from 'vue';
import { loadLocale } from '@/infrastructure/i18n';
import { wireModulesIntoCore } from '../../../../tests/support/unit/wireModules.ts';
import { ordersSchema } from '../schemas';
import enMessages from '../locales/en.json';
import itMessages from '../locales/it.json';

const setLocale = (locale: string) => loadLocale(locale).then(() => nextTick());

/** Every issue message a schema produces for a value, in the currently active locale. */
const messagesOf = (
    schema: { safeParse: (value: unknown) => { error?: { issues: { message: string }[] } } },
    value: unknown
) => schema.safeParse(value).error?.issues.map(({ message }) => message) ?? [];

describe('orders schema messages', () => {
    beforeAll(() => {
        wireModulesIntoCore();
        return setLocale('en');
    });
    afterEach(() => setLocale('en'));

    it('resolves every field message in Italian', () =>
        setLocale('it').then(() => {
            expect(messagesOf(ordersSchema, { email: 'nope', status: 'not-a-status' })).toEqual(
                expect.arrayContaining([
                    itMessages['orders-form']['email-invalid'],
                    itMessages['orders-form']['status-invalid']
                ])
            );
        }));
});

tests/unit/app/guards/localeChoice.spec..source:
/**
 * Locale router guard — `src/app/guards/localeChoice.ts`.
 *
 * This guard runs on every navigation and decides one of three things: proceed as-is, load a
 * language first, or redirect to inject a default locale. Getting the third case wrong is the
 * dangerous one — a guard that returns a redirect when it should return `true` produces an
 * infinite navigation loop, which is why the "already loaded" and "supported" branches are each
 * asserted to return the literal `true` rather than merely something truthy.
 *
 * `fetchLanguageApi` is the simulated server call underneath it. Its documented contract is that
 * it **always resolves, never rejects** — callers deliberately have no `.catch()` — so every
 * failure mode below asserts a resolved empty dictionary rather than a rejection.
 *
 * The i18n module is mocked so `supportedLanguages` / `loadedLanguages` are controlled by the
 * test rather than by whatever `VITE_APP_SUPPORTED_LOCALES` happens to hold in the developer's
 * `.env` — the suite must not change meaning when that file does.
 */

import { beforeEach, afterEach, describe, expect, it, vi } from 'vitest';
import type { RouteLocationNormalized } from 'vue-router';

/** Mutable so individual tests can decide what is supported / already loaded. */
const i18nState = {
    supportedLanguages: ['en', 'it', 'es'],
    loadedLanguages: [] as string[],
    currentLocale: 'en',
    defaultLocale: 'en'
};

// Parameters are declared even though the bodies ignore them: `vi.fn(() => ...)` infers a
// zero-arity signature, so the call sites below (and `toHaveBeenCalledWith`) would not type-check.
const changeLanguageMock = vi.fn((_locale: string) => Promise.resolve());
const updateLocaleMock = vi.fn((_locale: string, _messages: unknown) => Promise.resolve());

vi.mock('@/infrastructure/i18n', () => ({
    get supportedLanguages() {
        return i18nState.supportedLanguages;
    },
    get loadedLanguages() {
        return i18nState.loadedLanguages;
    },
    getCurrentLocale: () => i18nState.currentLocale,
    getDefaultLocale: () => i18nState.defaultLocale,
    changeLanguage: (locale: string) => changeLanguageMock(locale),
    updateLocale: (locale: string, messages: unknown) => updateLocaleMock(locale, messages),
    API_NAMESPACE: 'api'
}));

/**
 * The API's dictionary endpoints. Mocked at the network boundary rather than by stubbing
 * `withApiDictionary`, so the merge itself — this app's keys at the root, the API's under
 * `api.*` — is exercised by the assertions below instead of being replaced by them.
 */
const getLocalesMock = vi.fn(() => Promise.resolve({ data: { locales: ['en', 'it', 'es'] } }));
const getLocaleDictionaryMock = vi.fn(
    (_locale: string): Promise<{ data?: { messages?: Record<string, unknown> } }> =>
        Promise.resolve({ data: { messages: { greeting: 'from-the-api' } } })
);

vi.mock('@api', () => ({
    getLocales: () => getLocalesMock(),
    getLocaleDictionary: (locale: string) => getLocaleDictionaryMock(locale)
}));

const { fetchLanguageApi, localeChoice } = await import('@/app/guards/localeChoice');

/** Minimal route stub — the guard only reads name, params and query. */
const routeTo = (overrides: Partial<RouteLocationNormalized> = {}) =>
    ({
        name: 'home',
        params: {},
        query: {},
        ...overrides
    }) as unknown as RouteLocationNormalized;

beforeEach(() => {
    vi.clearAllMocks();
    localStorage.clear();
    i18nState.supportedLanguages = ['en', 'it', 'es'];
    i18nState.loadedLanguages = [];
    i18nState.currentLocale = 'en';
    i18nState.defaultLocale = 'en';
});

afterEach(() => {
    vi.useRealTimers();
});

describe('fetchLanguageApi', () => {
    it('resolves an empty dictionary for an unsupported locale, without waiting', () => {
        vi.useFakeTimers();

        // No timer is scheduled at all on this path, so the promise settles without any
        // advancement — asserted by resolving it before touching the clock.
        return fetchLanguageApi('kl').then((result) => {
            expect(result).toEqual(['kl', {}]);
            // Supported by neither side, so nothing is imported AND nothing is fetched.
            expect(getLocaleDictionaryMock).not.toHaveBeenCalled();
        });
    });

    it('loads a supported locale and returns its dictionary', () => {
        vi.useFakeTimers();
        const promise = fetchLanguageApi('en');
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return promise;
            })
            .then(([locale, dictionary]) => {
                expect(locale).toBe('en');
                // Real file, real import: asserting it is a non-empty object proves the dynamic import
                // actually resolved rather than falling into the catch branch.
                expect(Object.keys(dictionary).length).toBeGreaterThan(0);
            });
    });

    it('delays the first download of a locale by the simulated latency', () => {
        vi.useFakeTimers();
        const setTimeoutSpy = vi.spyOn(globalThis, 'setTimeout');

        void fetchLanguageApi('it');

        // Asserted on the scheduled delay rather than on when the promise settles: the dynamic
        // `import()` underneath resolves over an indeterminate number of microtasks, so a
        // settle-order assertion would be timing-dependent rather than behavioural.
        expect(setTimeoutSpy).toHaveBeenCalledWith(expect.any(Function), 1000);
    });

    it('skips the delay for a locale already downloaded in a previous session', () => {
        localStorage.setItem('downloaded-locales', JSON.stringify(['it']));
        vi.useFakeTimers();
        const setTimeoutSpy = vi.spyOn(globalThis, 'setTimeout');

        void fetchLanguageApi('it');

        // The whole point of persisting the list: latency is simulated once per browser, not
        // once per navigation.
        expect(setTimeoutSpy).toHaveBeenCalledWith(expect.any(Function), 0);
    });

    it('records a locale as downloaded once it has been fetched', () => {
        vi.useFakeTimers();
        const promise = fetchLanguageApi('it');
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return promise;
            })
            .then(() => {
                expect(JSON.parse(localStorage.getItem('downloaded-locales') ?? '[]')).toContain(
                    'it'
                );
            });
    });

    it('deduplicates the stored locale list', () => {
        localStorage.setItem('downloaded-locales', JSON.stringify(['en']));
        vi.useFakeTimers();
        const promise = fetchLanguageApi('en');
        return vi
            .advanceTimersByTimeAsync(0)
            .then(() => {
                return promise;
            })
            .then(() => {
                // Unbounded growth here would be a slow localStorage leak on a long-lived browser.
                expect(JSON.parse(localStorage.getItem('downloaded-locales') ?? '[]')).toEqual([
                    'en'
                ]);
            });
    });

    /**
     * The degradation design C is built around. `es` is supported and has no
     * `src/locales/es.json`, so the UI import rejects — and that must resolve to an empty UI
     * dictionary rather than reject, since callers have no `.catch`. The API's own copy is
     * fetched regardless, so the result is Spanish API messages inside a UI that falls back per
     * key: degrading key by key rather than all-or-nothing.
     */
    it('resolves API copy with an empty UI dictionary when the locale file does not exist', () => {
        vi.useFakeTimers();
        const promise = fetchLanguageApi('es');
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return expect(promise).resolves.toEqual([
                    'es',
                    { api: { greeting: 'from-the-api' } }
                ]);
            })
            .then(() => {
                expect(getLocaleDictionaryMock).toHaveBeenCalledWith('es');
            });
    });

    it('never rejects when the API dictionary cannot be fetched', () => {
        getLocaleDictionaryMock.mockRejectedValueOnce(new Error('network down'));
        vi.useFakeTimers();
        const promise = fetchLanguageApi('it');
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return promise;
            })
            .then(([locale, dictionary]) => {
                // The UI half still loaded; only `api.*` is empty. A dead API must never strand a
                // navigation or blank the interface.
                expect(locale).toBe('it');
                expect(dictionary.api).toEqual({});
                expect(Object.keys(dictionary).length).toBeGreaterThan(1);
            });
    });

    it('puts the API dictionary under api.* and never at the root', () => {
        // `navigation` is deliberately a namespace the SHARED dictionary owns. The module
        // dictionaries are not loaded here, so colliding on a module-owned namespace would prove
        // nothing — the root key would be absent whether or not the reserved namespace worked.
        getLocaleDictionaryMock.mockResolvedValueOnce({
            data: { messages: { navigation: { ['error-already-logged']: 'API COPY' } } }
        });
        vi.useFakeTimers();
        const promise = fetchLanguageApi('it');
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return promise;
            })
            .then(([, dictionary]) => {
                // The API's `navigation` key is namespaced, so it cannot shadow this app's own —
                // which is the collision the reserved namespace exists to prevent.
                expect(dictionary.api).toEqual({
                    navigation: { ['error-already-logged']: 'API COPY' }
                });
                expect(
                    (dictionary.navigation as Record<string, string>)['error-already-logged']
                ).not.toBe('API COPY');
            });
    });

    it('treats a corrupted downloaded-locales entry as empty rather than throwing', () => {
        localStorage.setItem('downloaded-locales', 'not-json{');
        vi.useFakeTimers();

        const promise = fetchLanguageApi('en');
        // Corrupted store ⇒ "not downloaded" ⇒ the full delay applies.
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => promise)
            .then(([locale, dictionary]) => {
                // The locale still loads for real...
                expect(locale).toBe('en');
                expect(Object.keys(dictionary).length).toBeGreaterThan(0);
                // ...and the corrupted value is replaced by a well-formed list, so the browser
                // self-heals instead of re-paying the latency on every navigation forever.
                expect(JSON.parse(localStorage.getItem('downloaded-locales') ?? 'null')).toEqual([
                    'en'
                ]);
            });
    });

    it('still resolves when localStorage writes are unavailable', () => {
        // Private-mode / quota: the documented behaviour is to swallow and simply re-simulate
        // the latency next time, never to fail the navigation.
        const setItemSpy = vi.spyOn(Storage.prototype, 'setItem').mockImplementation(() => {
            throw new Error('QuotaExceededError');
        });
        vi.useFakeTimers();
        const promise = fetchLanguageApi('en');
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return promise;
            })
            .then(([, dictionary]) => {
                expect(Object.keys(dictionary).length).toBeGreaterThan(0);
                setItemSpy.mockRestore();
            });
    });
});

describe('localeChoice', () => {
    it('proceeds without reloading when the locale is already loaded and active', () => {
        i18nState.loadedLanguages = ['en'];
        i18nState.currentLocale = 'en';
        return localeChoice(routeTo({ params: { locale: 'en' } })).then((result) => {
            // Literal `true`, not merely truthy: a redirect object is also truthy, and returning one
            // here is what produces an infinite navigation loop.
            expect(result).toBe(true);
            expect(changeLanguageMock).not.toHaveBeenCalled();
        });
    });

    it('switches the active language when the loaded locale differs from the current one', () => {
        i18nState.loadedLanguages = ['en', 'it'];
        i18nState.currentLocale = 'en';
        return localeChoice(routeTo({ params: { locale: 'it' } })).then((result) => {
            expect(result).toBe(true);
            expect(changeLanguageMock).toHaveBeenCalledWith('it');
            // Already loaded ⇒ no re-download.
            expect(updateLocaleMock).not.toHaveBeenCalled();
        });
    });

    it('fetches, registers and activates a supported but unloaded locale', () => {
        i18nState.loadedLanguages = [];
        i18nState.supportedLanguages = ['en', 'it'];
        vi.useFakeTimers();
        const promise = localeChoice(routeTo({ params: { locale: 'it' } }));
        return vi
            .advanceTimersByTimeAsync(1000)
            .then(() => {
                return promise;
            })
            .then((result) => {
                expect(result).toBe(true);
                // Order matters: messages must be registered before the language is switched, or the
                // first render after the switch has no translations.
                expect(updateLocaleMock).toHaveBeenCalledWith('it', expect.any(Object));
                expect(changeLanguageMock).toHaveBeenCalledWith('it');
            });
    });

    it('redirects an unsupported locale to the default, preserving route name and query', () => {
        i18nState.supportedLanguages = ['en', 'it'];
        i18nState.defaultLocale = 'en';
        return localeChoice(
            routeTo({
                name: 'products',
                params: { locale: 'kl', id: '42' },
                query: { page: '2' }
            })
        ).then((result) => {
            // Dropping params or query here would silently lose the user's place on every
            // locale-less deep link.
            expect(result).toEqual({
                name: 'products',
                params: { locale: 'en', id: '42' },
                query: { page: '2' }
            });
        });
    });

    it('redirects when the route carries no locale at all', () => {
        i18nState.defaultLocale = 'it';
        return localeChoice(routeTo({ name: 'home', params: {} })).then((result) => {
            expect(result).toEqual({
                name: 'home',
                params: { locale: 'it' },
                query: {}
            });
        });
    });

    it('does not activate any language while redirecting', () => {
        i18nState.supportedLanguages = ['en'];
        return localeChoice(routeTo({ params: { locale: 'zz' } })).then(() => {
            expect(changeLanguageMock).not.toHaveBeenCalled();
            expect(updateLocaleMock).not.toHaveBeenCalled();
        });
    });
});

