import { beforeEach, describe, expect, it } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import { useRealtimeObservabilityStore } from '@/modules/realtime/realtimeObservability';
import type { MetricsSnapshotEvent } from '@types';

// Minimal valid metrics payload used across tests
const makeSnapshot = (timestamp: string): MetricsSnapshotEvent => ({
    timestamp,
    uptimeSeconds: 60,
    memory: { rss: 1, heapUsed: 1, heapTotal: 2, external: 0 },
    http: { totalRequests: 10, totalErrors: 0 },
    realtime: { sseClients: 1 }
});

describe('useRealtimeObservabilityStore', () => {
    beforeEach(() => {
        // Fresh Pinia instance before every test so stores don't bleed state
        setActivePinia(createPinia());
    });

    it('initialises with idle status and no data', () => {
        const store = useRealtimeObservabilityStore();

        expect(store.status).toBe('idle');
        expect(store.latestSnapshot).toBeUndefined();
        expect(store.latestUpdate).toBeUndefined();
        expect(store.latestHeartbeatAt).toBeUndefined();
        expect(store.lastError).toBeUndefined();
    });

    it('updates status via setStatus', () => {
        const store = useRealtimeObservabilityStore();

        store.setStatus('connecting');
        expect(store.status).toBe('connecting');

        store.setStatus('open');
        expect(store.status).toBe('open');
    });

    it('stores a metrics snapshot via setSnapshot', () => {
        const store = useRealtimeObservabilityStore();
        const snapshot = makeSnapshot('2026-01-01T00:00:00.000Z');

        store.setSnapshot(snapshot);

        expect(store.latestSnapshot).toEqual(snapshot);
    });

    it('stores a metrics update via setUpdate', () => {
        const store = useRealtimeObservabilityStore();
        const update = makeSnapshot('2026-01-01T00:01:00.000Z');

        store.setUpdate(update);

        expect(store.latestUpdate).toEqual(update);
    });

    it('records only the timestamp from a heartbeat payload via setHeartbeat', () => {
        const store = useRealtimeObservabilityStore();
        const heartbeat = makeSnapshot('2026-01-01T00:02:00.000Z');

        store.setHeartbeat(heartbeat);

        expect(store.latestHeartbeatAt).toBe('2026-01-01T00:02:00.000Z');
        // snapshot and update remain untouched
        expect(store.latestSnapshot).toBeUndefined();
        expect(store.latestUpdate).toBeUndefined();
    });

    it('stores the latest error message via setError', () => {
        const store = useRealtimeObservabilityStore();

        store.setError('connection lost');

        expect(store.lastError).toBe('connection lost');
    });

    it('overwrites previous values when actions are called again', () => {
        const store = useRealtimeObservabilityStore();

        store.setSnapshot(makeSnapshot('2026-01-01T00:00:00.000Z'));
        store.setSnapshot(makeSnapshot('2026-01-02T00:00:00.000Z'));

        expect(store.latestSnapshot?.timestamp).toBe('2026-01-02T00:00:00.000Z');
    });
});

src/modules/inventory/tests/store.spec.t.source:
/**
 * The inventory store — transport-mocked like the wishlist's spec.
 *
 * Worth pinning: both reads are whole-list replacement (the page renders what the API answered),
 * and both writes reload what they changed BEFORE answering, so a caller never sees a counter the
 * views have not caught up with. The order of those reloads is asserted rather than assumed — the
 * ledger explains the board, and a board that arrived first reads as a number nobody wrote.
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';
import { useInventoryStore } from '@/modules/inventory/store.ts';
import { orvalMutator } from '@/infrastructure/http';

const MOVEMENT = {
    id: 'movement-1',
    productId: 'p1',
    reason: 'reserve',
    onHandDelta: 0,
    reservedDelta: 2
};

const LEVEL = { productId: 'p1', title: 'Product one', onHand: 24, reserved: 2, available: 22 };

let responses: Record<string, unknown>;

vi.mock('@/infrastructure/http', () => ({
    orvalMutator: vi.fn((config: { url: string; method: string }) => {
        const key = `${config.method?.toUpperCase()} ${config.url}`;
        return Promise.resolve(responses[key]);
    })
}));

const requestedUrls = () =>
    vi.mocked(orvalMutator).mock.calls.map((call) => (call[0] as { url: string }).url);

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    responses = {
        'GET /inventory/movements': { data: { items: [MOVEMENT] } },
        'GET /inventory/levels': { data: { items: [LEVEL] } },
        'POST /inventory/receipts': { data: LEVEL },
        'POST /inventory/adjustments': { data: LEVEL }
    };
});

describe('fetchMovements', () => {
    it('replaces the ledger with what the API answered', () => {
        const store = useInventoryStore();
        return store.fetchMovements().then(() => {
            expect(store.movements.map(({ id }) => id)).toEqual(['movement-1']);
        });
    });

    it('reads a payload with no items as an empty ledger, not a crash', () => {
        responses['GET /inventory/movements'] = { data: undefined };
        const store = useInventoryStore();
        return store.fetchMovements().then(() => {
            expect(store.movements).toEqual([]);
        });
    });

    it('narrows to one product by passing the id through as a query param', () => {
        const store = useInventoryStore();
        return store.fetchMovements('p1').then(() => {
            const call = vi.mocked(orvalMutator).mock.calls[0]![0] as {
                params?: { productId?: string };
            };
            expect(call.params).toEqual({ productId: 'p1' });
        });
    });
});

describe('fetchLevels', () => {
    it('replaces the board with what the API answered', () => {
        const store = useInventoryStore();
        return store.fetchLevels().then(() => {
            expect(store.levels).toEqual([LEVEL]);
        });
    });

    it('reads a payload with no items as an empty board, not a crash', () => {
        responses['GET /inventory/levels'] = { data: undefined };
        const store = useInventoryStore();
        return store.fetchLevels().then(() => {
            expect(store.levels).toEqual([]);
        });
    });
});

describe('receive', () => {
    it('answers the counters the API reported and reloads both views it changed', () => {
        const store = useInventoryStore();
        return store.receive('p1', 20).then((level) => {
            expect(level).toEqual(LEVEL);
            // The reload is the point, and so is its order: the ledger explains the board.
            expect(requestedUrls()).toEqual([
                '/inventory/receipts',
                '/inventory/movements',
                '/inventory/levels'
            ]);
        });
    });

    it('sends the quantity as a receipt body rather than a query param', () => {
        const store = useInventoryStore();
        return store.receive('p1', 20).then(() => {
            const call = vi.mocked(orvalMutator).mock.calls[0]![0] as { data?: unknown };
            expect(call.data).toEqual({ productId: 'p1', quantity: 20 });
        });
    });

    it('reads a bare payload as no counters, not a crash', () => {
        responses['POST /inventory/receipts'] = { data: undefined };
        const store = useInventoryStore();
        return store.receive('p1', 20).then((level) => {
            expect(level).toBeUndefined();
        });
    });
});

describe('adjust', () => {
    it('passes the delta through signed, because shrinkage is the common case', () => {
        const store = useInventoryStore();
        return store.adjust('p1', -3).then(() => {
            const call = vi.mocked(orvalMutator).mock.calls[0]![0] as { data?: unknown };
            expect(call.data).toEqual({ productId: 'p1', delta: -3 });
        });
    });

    it('reloads both views it changed, exactly as a receipt does', () => {
        const store = useInventoryStore();
        return store.adjust('p1', -3).then(() => {
            expect(requestedUrls()).toEqual([
                '/inventory/adjustments',
                '/inventory/movements',
                '/inventory/levels'
            ]);
        });
    });
});

tests/cross-cutting/registry.spec.ts.source:
/**
 * Invariants every enabled module must satisfy, whichever modules those are.
 *
 * This is the shape a cross-cutting spec is allowed to take: it **iterates** the registry and
 * never **names** a domain. Delete `products` and this file keeps passing, testing one module
 * fewer — which is exactly what `docs/theory/modules.md` asks of a spec that lives outside a
 * module.
 *
 * The property is "every menu entry any module contributes points at a route that module
 * declares, and every route it declares is reachable" — not "products is in the menu and is
 * public". A hardcoded phrasing breaks when a domain is removed; this one does not.
 *
 * The failure it exists to catch is a silent one: a `navigation` entry naming a route that does
 * not exist renders a link that resolves to nothing. `vue-router` warns in the console and
 * carries on, so a human clicking around finds it and no gate does.
 */
import { describe, expect, it } from 'vitest';
import type { RouteRecordRaw } from 'vue-router';
import { enabledModules } from '@/modules';
import type { TranslationDictionaries } from '@/infrastructure/i18n';
import { validateModules } from '@/kernel/registry';

/** Every route name a record tree declares, at any depth. */
const routeNamesOf = (routes: RouteRecordRaw[]): string[] =>
    routes.flatMap((route) => [
        ...(typeof route.name === 'string' ? [route.name] : []),
        ...routeNamesOf(route.children ?? [])
    ]);

const moduleCases = enabledModules.map((appModule) => [appModule.name, appModule] as const);

describe('the enabled registry', () => {
    it('is internally consistent — no duplicate name, no unknown or cyclic dependency', () => {
        expect(() => validateModules(enabledModules)).not.toThrow();
    });

    it('enables at least one module, so the sweeps below are not vacuously true', () => {
        expect(enabledModules.length).toBeGreaterThan(0);
    });

    it('declares every dependency as a module that is itself enabled', () => {
        const names = new Set(enabledModules.map(({ name }) => name));

        for (const { dependsOn = [] } of enabledModules)
            for (const edge of dependsOn) expect(names).toContain(edge.module);
    });
});

describe.each(moduleCases)('module %s', (_name, appModule) => {
    it('contributes navigation entries that point at routes it declares', () => {
        const declared = new Set(routeNamesOf(appModule.routes));

        for (const { name } of appModule.navigation ?? []) expect(declared).toContain(name);
    });

    it('gives every navigation entry an order, so it cannot silently sink to the bottom', () => {
        for (const entry of appModule.navigation ?? []) expect(entry.order).toBeTypeOf('number');
    });

    it('names every route it declares — the navigation and the guards address routes by name', () => {
        for (const route of appModule.routes) expect(typeof route.name).toBe('string');
    });
});

/**
 * Dictionary collisions.
 *
 * Nesting every key under its module (`products.list.page-title` rather than
 * `products-list-page.page-title`) would make a collision impossible by construction, but it
 * touches every `.vue` file and every JSON, and keys already carry a domain prefix by convention.
 * This catches the same failure at roughly none of the cost.
 *
 * The failure: dictionaries are DEEP-MERGED at boot, in registration order. If two modules declare
 * the same top-level key, the later one's entries win and the earlier one's copy vanishes. Nothing
 * throws. The page renders raw keys, and only a human reading the screen in that language notices.
 *
 * `navigation` is the deliberate exception — every module contributes its own `label-*` slice of
 * it, which is exactly why the merge has to be deep. So it is checked one level lower instead:
 * co-owning the namespace is fine, claiming the same entry inside it is not.
 */
const CO_OWNED_NAMESPACE = 'navigation';

/** Locale codes any enabled module ships, deduplicated. */
const localeCodes = [
    ...new Set(enabledModules.flatMap((appModule) => Object.keys(appModule.locales ?? {})))
];

/** Every contributor's dictionary for one locale, the shared one included, labelled by owner. */
const dictionariesFor = (
    locale: string
): Promise<{ owner: string; dictionary: TranslationDictionaries }[]> =>
    Promise.all([
        (import(`@/locales/${locale}.json`) as Promise<{ default: TranslationDictionaries }>).then(
            ({ default: dictionary }) => ({ owner: '<shared>', dictionary })
        ),
        ...enabledModules
            .filter((appModule) => appModule.locales?.[locale])
            .map((appModule) =>
                appModule.locales![locale]().then((dictionary) => ({
                    owner: appModule.name,
                    dictionary
                }))
            )
    ]);

/** key → the contributors that declare it, for anything declared more than once. */
const clashesIn = (entries: { owner: string; keys: string[] }[]): Record<string, string[]> => {
    const owners: Record<string, string[]> = {};

    for (const { owner, keys } of entries) for (const key of keys) (owners[key] ??= []).push(owner);

    return Object.fromEntries(
        Object.entries(owners).filter(([, contributors]) => contributors.length > 1)
    );
};

describe.each(localeCodes)('locale dictionaries — %s', (locale) => {
    it('gives every top-level namespace exactly one owner', () =>
        dictionariesFor(locale).then((loaded) => {
            const clashes = clashesIn(
                loaded.map(({ owner, dictionary }) => ({
                    owner,
                    keys: Object.keys(dictionary).filter((key) => key !== CO_OWNED_NAMESPACE)
                }))
            );

            // Named rather than counted: the message has to say WHICH namespace and WHO, or the
            // failure is a scavenger hunt through seven JSON files.
            expect(clashes).toEqual({});
        }));

    it(`gives every ${CO_OWNED_NAMESPACE} entry exactly one owner, though the namespace is shared`, () =>
        dictionariesFor(locale).then((loaded) => {
            const clashes = clashesIn(
                loaded.map(({ owner, dictionary }) => ({
                    owner,
                    keys: Object.keys(
                        (dictionary[CO_OWNED_NAMESPACE] as TranslationDictionaries | undefined) ??
                            {}
                    )
                }))
            );

            expect(clashes).toEqual({});
        }));

    it('is shipped by every module, so no domain is untranslated in this language', () => {
        const missing = enabledModules
            .filter((appModule) => appModule.locales && !appModule.locales[locale])
            .map(({ name }) => name);

        expect(missing).toEqual([]);
    });
});

tests/unit/infrastructure/stores/session.source:
/**
 * `persistLocalePreference` — `src/infrastructure/stores/session.ts`.
 *
 * The one write the session store makes that is not about the session itself, and the reason
 * `AppLanguageSwitcher` does not know what a session is. Every case below is the same claim from
 * a different side: **choosing a language always succeeds, whatever the account endpoint does.**
 *
 * The store is real — `isAuth` derives from token AND viewer, and stubbing it would test the stub.
 * Only `@api` is mocked, at the network boundary.
 */
import { describe, it, expect, beforeEach, vi } from 'vitest';
import { createPinia, setActivePinia } from 'pinia';

const updateAccountMock = vi.fn();

vi.mock('@api', () => ({
    getAccount: vi.fn(),
    refreshToken: vi.fn(),
    logout: vi.fn(),
    logoutAll: vi.fn(),
    updateAccount: (body: { locale: string }) => updateAccountMock(body)
}));

const { useSessionStore } = await import('@/infrastructure/stores/session.ts');

/** A store with a token AND a viewer, which is what `isAuth` actually requires. */
const signedIn = () => {
    const store = useSessionStore();
    store.setAccessToken('token');
    store.setViewer({ id: '1', email: 'a@b.c', admin: false });
    return store;
};

beforeEach(() => {
    setActivePinia(createPinia());
    vi.clearAllMocks();
    updateAccountMock.mockResolvedValue({ data: {} });
});

describe('persistLocalePreference', () => {
    it('writes the choice onto a signed-in visitor’s account', () => {
        return signedIn()
            .persistLocalePreference('it')
            .then(() => {
                expect(updateAccountMock).toHaveBeenCalledWith({ locale: 'it' });
            });
    });

    /*
     * The rule that used to live at the call site. A guest has no record to write to, so the call
     * is not made at all — an anonymous `PUT /account` would answer 401 and teach nobody anything.
     */
    it('does not call the API for a guest', () => {
        return useSessionStore()
            .persistLocalePreference('it')
            .then(() => {
                expect(updateAccountMock).not.toHaveBeenCalled();
            });
    });

    /* A token with no viewer is a session restored but not yet identified — not signed in. */
    it('does not call the API for a token whose holder is still unknown', () => {
        const store = useSessionStore();
        store.setAccessToken('token');
        return store.persistLocalePreference('it').then(() => {
            expect(updateAccountMock).not.toHaveBeenCalled();
        });
    });

    it('resolves rather than rejecting when the write fails', () => {
        updateAccountMock.mockRejectedValue(new Error('account service down'));
        return expect(signedIn().persistLocalePreference('it')).resolves.toBeUndefined();
    });

    /*
     * Stated as its own case because it is the whole point of the seam: the switcher fires this
     * without awaiting it, so a rejection that escaped would surface as an unhandled rejection in
     * the console of a page that switched language perfectly well.
     */
    it('resolves with nothing on the happy path too, so the caller can ignore it', () => {
        return expect(signedIn().persistLocalePreference('en')).resolves.toBeUndefined();
    });
});

tests/cross-cutting/contextMap.spec.ts.source:
/**
 * The context map, asserted against the code it describes.
 *
 * `dependsOn` in each manifest is not a dependency list — it is a labelled graph, where every edge
 * says which sibling is reached and what kind of relationship that is. A label nobody checks is a
 * comment with extra syntax, so this file holds it to three things:
 *
 *   1. **The edge is real.** A declared dependency that nothing imports is a claim about coupling
 *      that has already been undone — and this client had one for months: `cart` kept
 *      `dependsOn: ['orders']` after checkout moved into the cart store and the import went away.
 *   2. **The edge is declared.** The reverse: an import across a module boundary that no edge
 *      names. ESLint stops a module reaching a sibling's internals; nothing until now stopped it
 *      reaching a sibling it never admitted to needing.
 *   3. **Every edge has a reason a human wrote.**
 *
 * `.vue` files are scanned as well as `.ts`. On a client most cross-module reach happens in a
 * component — `Order.vue` calling `useCartStore`, the catalogue mounting an add-to-cart button —
 * so a sweep that read only TypeScript would miss the majority of the real graph.
 *
 * Imports are read from source rather than resolved: the question is what the code SAYS, and a spec
 * that needed the app mounted to answer it would be an e2e test.
 */

import { describe, expect, it } from 'vitest';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { enabledModules } from '@/modules';
import type { ContextRelationship } from '@/kernel/registry';

const MODULES_ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '../../src/modules');

/** Every `.ts` and `.vue` file below `directory`, recursively. */
const listFiles = (directory: string): string[] =>
    readdirSync(directory).flatMap((entry) => {
        const entryPath = path.join(directory, entry);
        if (statSync(entryPath).isDirectory()) return listFiles(entryPath);
        return /\.(ts|vue)$/.test(entryPath) ? [entryPath] : [];
    });

/**
 * Which siblings a module's production code imports.
 *
 * Specs and mocks are excluded deliberately. A fixture may name another domain's data — that is
 * what `mockSeeds.after` is for, a separate graph — and counting it here would make every module
 * look coupled to every module it borrows sample data from.
 */
const importedSiblings = (owner: string): Set<string> => {
    const siblings = new Set<string>();
    for (const file of listFiles(path.join(MODULES_ROOT, owner))) {
        if (/[/\\](tests|mocks)[/\\]/.test(file)) continue;
        for (const match of readFileSync(file, 'utf8').matchAll(/["']@\/modules\/([^"'/]+)/g))
            if (match[1] !== owner) siblings.add(match[1]);
    }
    return siblings;
};

/** `<from>→<to>` for every declared edge, with its kind. */
const declaredEdges = (): { from: string; to: string; as: ContextRelationship }[] =>
    enabledModules.flatMap((appModule) =>
        (appModule.dependsOn ?? []).map((edge) => ({
            from: appModule.name,
            to: edge.module,
            as: edge.as
        }))
    );

describe('the context map describes the imports that exist', () => {
    it('finds the modules it is meant to check', () => {
        // A canary: an empty sweep must mean "nothing depends on anything", not "the sweep broke".
        expect(declaredEdges().length).toBeGreaterThanOrEqual(6);
    });

    it('declares no edge that nothing imports', () => {
        const stale = declaredEdges()
            .filter(({ from, to }) => !importedSiblings(from).has(to))
            .map(({ from, to }) => `${from} declares ${to}, but imports nothing from it`);

        expect(stale).toEqual([]);
    });

    it('imports no sibling that no edge declares', () => {
        const undeclared: string[] = [];

        for (const appModule of enabledModules) {
            const declared = new Set((appModule.dependsOn ?? []).map((edge) => edge.module));
            for (const sibling of importedSiblings(appModule.name))
                if (!declared.has(sibling))
                    undeclared.push(
                        `${appModule.name} imports ${sibling}, but declares no edge to it`
                    );
        }

        expect(undeclared).toEqual([]);
    });

    it('gives every edge a reason a human wrote', () => {
        // Not a style check. An edge whose reason cannot be stated in a sentence is usually two
        // edges, or a boundary drawn in the wrong place.
        const unexplained = enabledModules.flatMap((appModule) =>
            (appModule.dependsOn ?? [])
                .filter((edge) => edge.because.trim().length < 20)
                .map((edge) => `${appModule.name} → ${edge.module}`)
        );

        expect(unexplained).toEqual([]);
    });

    it('reaches a sibling only for state it asks to change, or vocabulary it can hold', () => {
        // The client's own version of "keep shared kernels rare". There is no `shared-kernel` on
        // this side at all — the server is the only writer — so every edge has to be one of the
        // three cheaper kinds, and a fourth appearing means the client has started owning state
        // that the API owns.
        const kinds = new Set(declaredEdges().map(({ as }) => as));
        expect([...kinds].toSorted()).toEqual(
            ['conformist', 'customer-supplier', 'published-language'].filter((kind) =>
                kinds.has(kind as ContextRelationship)
            )
        );
    });
});

